custom_fields.glyph:
[[[
const card = this;
if (!card._casoraAssistBound) {
card._casoraAssistBound = true;
const openIt = (e) => {
if (card._casoraAssistGuardUntil && Date.now() < card._casoraAssistGuardUntil) return;
card._casoraAssistGuardUntil = Date.now() + 600;
if (e.type === 'touchend' && e.cancelable) e.preventDefault();
if (e.type === 'touchend') { try { card.dispatchEvent(new CustomEvent('haptic', { detail: 'light', bubbles: true, composed: true })); } catch (x) {} }
if (window._casoraAssist && window._casoraAssist.open()) return;
const root = document.querySelector('home-assistant') || card;
root.dispatchEvent(new CustomEvent('hass-action', {
bubbles: true, composed: true,
detail: { config: { tap_action: { action: 'assist' } }, action: 'tap' },
}));
};
card.addEventListener('touchend', openIt, { passive: false });
card.addEventListener('click', openIt);
}
return `<img class="casora-assist" src="${window.casoraIconUrl('assist-fill')}"
    alt="" aria-hidden="true">`;
]]]

casora_assist_button.extra_styles:
:host{
  --button-card-ripple-color: transparent !important;
  --button-card-ripple-hover-color: transparent !important;
  --ha-ripple-color: transparent !important;
  --ha-ripple-hover-color: transparent !important;
  --mdc-ripple-press-opacity: 0 !important;
}
:host ha-ripple,
:host mwc-ripple{ display: none !important; }
:host{
  display: grid !important;
  place-items: center !important;
  position: relative !important;
  width: var(--casora-chrome-btn-size, 34px) !important;
  height: var(--casora-chrome-btn-size, 34px) !important;
  color: var(--casora-chrome-ink, #fff) !important;
  pointer-events: auto !important;
}
:host ha-card{
  display: var(--casora-assist-vis, none) !important;
  position: relative !important;
  width: var(--casora-chrome-btn-size, 34px) !important;
  height: var(--casora-chrome-btn-size, 34px) !important;
  border-radius: 50% !important;
  place-items: center !important;
  background: var(--casora-assist-fill, var(--casora-chrome-btn-fill, var(--casora-chrome-fill, rgba(0,0,0,0.40)))) !important;
  /* Weich (1.0.7, Kopfleiste D): Fläche mit weichem Schatten über Theme-Variablen, sonst flach. */
  /* Kopfknöpfe A (1.3): in der Kapsel ohne eigenen Blur (--casora-chrome-btn-backdrop setzt casora_room) –
     sonst verwischte jeder Kreis die Kapselkante darunter, links und rechts lag ein grauer Schleier. */
  backdrop-filter: var(--casora-chrome-btn-backdrop, var(--casora-chrome-backdrop, none)) !important;
  -webkit-backdrop-filter: var(--casora-chrome-btn-backdrop, var(--casora-chrome-backdrop, none)) !important;
  /* 1.3: in der Kapsel (Kopfknöpfe A) ohne eigenen Schatten – --casora-chrome-btn-shadow setzt casora_room. */
  box-shadow: var(--casora-chrome-btn-shadow, var(--casora-chrome-shadow, none)) !important;
  transition: background var(--casora-dur-feedback, 180ms) var(--casora-ease-feedback, cubic-bezier(.32,.72,0,1)) !important;
}
:host .vertical,
:host .ellipsis,
:host .custom-field,
:host .custom-field-glyph{ overflow: visible !important; }
/* Height only: the viewBox is wider than tall, so fixing both squashes it. */
:host .casora-assist{
  position: absolute !important;
  top: 50% !important;
  left: 50% !important;
  transform: translate(-50%, -50%) !important;
  height: var(--casora-assist-size, 16px) !important;
  width: auto !important;
  display: block !important;
  pointer-events: none !important;
  /* Weisses <img>-Glyph: helle Themes färben es per Filter um. */
  filter: var(--casora-chrome-glyph-filter, none) !important;
}
@media (hover: hover) and (pointer: fine){
  :host ha-card:hover{
    background: var(--casora-assist-fill, var(--casora-chrome-fill-hover, rgba(0,0,0,0.55))) !important;
  }
}

/* Weich (1.0.7): Symbole etwas leichter (--casora-chrome-glyph-opacity, sonst 1). */
:host .casora-assist{ opacity: var(--casora-chrome-glyph-opacity, 1); }

/* Handy-Leiste B (1.3): in der Navigationsleiste ist der Kreis 36 – die Trefferfläche wächst unsichtbar
   auf 48 (--casora-chrome-hit setzt casora-mobile-nav), sonst 0. */
:host ha-card{ overflow: visible !important; }
:host ha-card::before{ content: ""; position: absolute; inset: calc(-1 * var(--casora-chrome-hit, 0px)); border-radius: 50%; }

/* Ohne eigene Tipp-Aktion (Klick hört am Host) setzt button-card ha-card.disabled = pointer-events:none –
   dann griff :hover nie, die Kreise hatten am Desktop keinen Mouse-over (11.10.2026). */
:host ha-card.disabled{ pointer-events: auto !important; cursor: pointer !important; }

