casora_badge_base.extra_styles:
:host{
  --badge-sub-opacity: var(--casora-badge-sub-opacity, .80);
  --badge-after-z:  2;
  --badge-before-z: 3;
  --casora-badge-hover-shadow: none;

  /* Sub-badge entrance */
  --casora-badge-enter-t: var(--casora-row-fade, 1);
  --casora-badge-enter-p: calc(1 - var(--casora-badge-enter-t));
  --casora-badge-enter-lift: -22px;
  --casora-badge-enter-depth: 0.24;
  --casora-badge-enter-origin: 50% -45%;
  --casora-badge-enter-dur: calc(0.30s + var(--casora-badge-enter-t) * 0.12s);
  --casora-badge-enter-fade: calc(0.18s + var(--casora-badge-enter-t) * 0.04s);
  --casora-badge-enter-squash: 0.08;
  --casora-badge-enter-transform:
    translateX(calc(var(--casora-badge-enter-p) * var(--casora-badge-converge-x, 0px)))
    translateY(calc(var(--casora-badge-enter-p) * var(--casora-badge-enter-lift)))
    scaleX(calc(1 - var(--casora-badge-enter-p) *
      (var(--casora-badge-enter-depth) - var(--casora-badge-enter-squash))))
    scaleY(calc(1 - var(--casora-badge-enter-p) *
      (var(--casora-badge-enter-depth) + var(--casora-badge-enter-squash))));
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  :host {
    --casora-badge-enter-lift: 0px !important;
    --casora-badge-enter-depth: 0 !important;
    --casora-badge-enter-squash: 0 !important;
    --casora-badge-converge-x: 0px !important;
  }
  :host ha-card {
    --casora-badge-enter-delay: 0ms !important;
  }
}

@media (max-width: 767px) and (orientation: portrait) {
  ha-card {
    min-height: var(--badge-min-height-current, 43px) !important;
    padding: var(--badge-padding-current, 1px 14px 1px 6px) !important;
    /* Nie breiter als der Bildschirm abzüglich Rand (01.10.2026): lange Zusammenfassungen
       („1 Schloss · 2 Fenster offen · …“) enden mit „…“ in der Pille statt rechts aus dem Bild. */
    max-width: calc(100vw - 2 * var(--casora-badge-row-gutter, 16px)) !important;
  }
  #img-cell, .img-cell {
    width: var(--badge-icon-size-current, 32px) !important;
    height: var(--badge-icon-size-current, 32px) !important;
  }
  #name { font-size: var(--badge-font-size-current, 13px) !important; }
  .badge-title { font-size: var(--badge-font-size-current, 13px) !important; }
  .badge-sub { font-size: calc(var(--badge-font-size-current, 13px) * var(--badge-sub-scale, 1) - var(--badge-sub-delta, 1px)) !important; }
}

@media (max-height: 600px) and (orientation: landscape) {
  ha-card {
    min-height: var(--badge-min-height-current, 36px) !important;
    padding: var(--badge-padding-current, 1px 12px 1px 6px) !important;
  }
  #img-cell, .img-cell {
    width: var(--badge-icon-size-current, 26px) !important;
    height: var(--badge-icon-size-current, 26px) !important;
  }
  #name { font-size: var(--badge-font-size-current, 12px) !important; }
  .badge-title { font-size: var(--badge-font-size-current, 12px) !important; }
  .badge-sub { font-size: calc(var(--badge-font-size-current, 12px) * var(--badge-sub-scale, 1) - var(--badge-sub-delta, 1px)) !important; }
}

/* Tablet (touch, 768-1400px) */
@media (min-width: 768px) and (max-width: 1400px) and (min-height: 501px) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1400px) and (min-height: 501px) and (hover: none) {
  :host {
    --badge-icon-size-current: var(--badge-icon-size-tablet, 26px) !important;
    --badge-min-height-current: var(--badge-min-height-tablet, 40px) !important;
    --badge-padding-current: var(--badge-padding-tablet, 7px 14px 8px 7px) !important;
    --badge-font-size-current: var(--badge-font-size-tablet, 13px) !important;
  }
  #img-cell, .img-cell {
    width: var(--badge-icon-size-current, 26px) !important;
    height: var(--badge-icon-size-current, 26px) !important;
  }
  #name { font-size: var(--badge-font-size-current, 13px) !important; }
  .badge-title { font-size: var(--badge-font-size-current, 13px) !important; }
  .badge-sub { font-size: calc(var(--badge-font-size-current, 13px) * var(--badge-sub-scale-tablet, var(--badge-sub-scale, 1)) - var(--badge-sub-delta, 1px)) !important; }
}

:host ha-card {
  /* Stagger In */
  --casora-badge-enter-delay-current:
    calc(var(--casora-badge-enter-delay, 0ms) * var(--casora-badge-enter-t));

  opacity: var(--casora-badge-enter-t);
  transform-origin: var(--casora-badge-enter-origin);
  transform: var(--casora-badge-enter-transform);
  translate: var(--casora-badge-flip-x, 0px);
  box-shadow: var(--casora-badge-glass-rim, none) !important;
  transition: background-color .22s ease,
              box-shadow .24s ease,
              translate var(--casora-badge-flip-dur, 0.42s)
                        var(--casora-badge-flip-ease, cubic-bezier(0.32, 0.72, 0, 1)),
              /* Geometry holds its value for --casora-badge-hold, non-zero
                 only while hiding, so the badge keeps its size until its
                 field finishes closing over it. Zero (instant) otherwise. */
              max-width 0s var(--casora-badge-hold, 0s),
              padding 0s var(--casora-badge-hold, 0s),
              min-height 0s var(--casora-badge-hold, 0s),
              transform var(--casora-badge-enter-dur) var(--casora-badge-enter-ease, cubic-bezier(0.34, 1.26, 0.44, 1)) var(--casora-badge-enter-delay-current),
              filter .18s ease,
              opacity var(--casora-badge-enter-fade) ease var(--casora-badge-enter-delay-current) !important;
}

ha-card:not(#casora-badge-shadow-suppress):hover {
  box-shadow: var(--casora-badge-glass-rim, none) !important;
  opacity: 0.99 !important;
}

@media (max-width: 767px), (max-height: 600px) {
  ha-card { --casora-badge-glass-rim: var(--casora-badge-shadow-mobile, none); }
}

ha-card::after{  z-index: var(--badge-after-z, 2) !important; }
ha-card::before{ z-index: var(--badge-before-z, 3) !important; }

#img-cell{
  width:  var(--badge-icon-size-current, var(--badge-icon-size, 30px)) !important;
  height: var(--badge-icon-size-current, var(--badge-icon-size, 30px)) !important;
  border-radius: 9999px !important;
  overflow: hidden !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  /* Fix-Runde 1 (A-04): Symbolkreis in Gerätefarbe. --casora-badge-circle-mix ist nur in Weich
     gesetzt (100 %); ohne ihn bleibt der Kreis durchsichtig wie bisher. Die Farbe kommt aus
     --casora-badge-tone (Aus-Zustände) bzw. der Symbolfarbe des jeweiligen Badges. */
  background: var(--casora-badge-icon-bg, color-mix(in srgb,
    var(--casora-badge-tone, var(--casora-badge-icon-color, var(--casora-icon-color, transparent)))
    var(--casora-badge-circle-mix, 0%), transparent)) !important;
}

/* Glyph im Kreis: weiß (bzw. --casora-badge-glyph) und kleiner – nur bei gesetztem Kreis-Mix. */
#img-cell ha-state-icon, #img-cell > ha-icon {
  scale: var(--casora-badge-glyph-scale, none);
}

#img-cell img,
#img-cell ha-img{
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  display: block !important;
  border-radius: inherit !important;
}

#icon{
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  pointer-events: none !important;
}

#icon ha-icon,
#icon ha-svg-icon,
#img-cell{
  pointer-events: none !important;
}

#name{
  display:flex !important;
  align-items:center !important;
  min-width: 0 !important;
  overflow: hidden !important;
  line-height: normal !important;
}

.badge-wrap{
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  gap: 1px;
  min-width:0;
  max-width:100%;
  padding-top: 0 !important;
  padding-bottom: 0 !important;
}

.badge-title{
  font-size: var(--badge-font-size-current, 13px);
  font-weight: 700;
  line-height: 1.2;
  color: var(--badge-title-color, var(--secondary-text-color));
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  /* Spalte (align-items:flex-start) dehnt nicht: ohne Grenze lief ein langer Name
     über den Badge-Rand hinaus und wurde hart abgeschnitten statt mit „…“ (d-kacheln, 1.3). */
  max-width:100%;
}

.badge-sub{
  font-size: calc(var(--badge-font-size-current, 13px) * var(--badge-sub-scale, 1) - var(--badge-sub-delta, 1px));
  font-weight: 500;
  line-height: 1.2;
  opacity: var(--badge-sub-opacity, .82);
  color: var(--badge-sub-color, var(--secondary-text-color));
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
  /* Spalte (align-items:flex-start) dehnt nicht: ohne Grenze lief ein langer Name
     über den Badge-Rand hinaus und wurde hart abgeschnitten statt mit „…“ (d-kacheln, 1.3). */
  max-width:100%;
}

card.display:
[[[
const v = variables?.enabled;
if (v === undefined || v === null) return 'inline-grid';
if (typeof v === 'boolean') return v ? 'inline-grid' : 'none';
if (typeof v === 'number') return v !== 0 ? 'inline-grid' : 'none';
const s = String(v).trim().toLowerCase();
if (['false','0','no','off','disabled'].includes(s)) return 'none';
return 'inline-grid';
]]]

card.--casora-badge-enter-delay:
[[[
const step = Number(variables?.enter_step ?? 22);
let i = 0;
try {
const sibs = this.parentElement?.children;
if (sibs && sibs.length > 1) {
for (const el of sibs) {
if (el === this) break;
if (el.localName !== this.localName) continue;
const c = el.shadowRoot && el.shadowRoot.querySelector('ha-card');
if (c && c.style.display === 'none') continue;
i++;
}
}
} catch (e) {}
return i > 0 ? (i * step) + 'ms' : 'inherit';
]]]

casora_camera_alert_helper.value:
[[[
if (typeof window.casoraCameraAlert !== 'function') {
window.casoraCameraAlert = function (hass, states, cams, windowMinutes) {
const reg = (hass && hass.entities) || {};
const devs = {};
cams.forEach(function (id) {
const d = reg[id] && reg[id].device_id;
if (d) devs[d] = true;
});
const span = (Number(windowMinutes) > 0 ? Number(windowMinutes) : 5) * 60000;
const now = Date.now();
states['sensor.time'];
let ding = false, motion = false;
Object.keys(reg).forEach(function (id) {
if (id.indexOf('event.') !== 0) return;
if (!devs[reg[id].device_id]) return;
const t = Date.parse(states[id] && states[id].state);
if (!isFinite(t) || now - t > span) return;
if (/ding|doorbell|button/.test(id)) ding = true;
else if (/motion/.test(id)) motion = true;
});
return ding ? 'Klingel' : motion ? 'Bewegung erkannt' : '';
};
}
return true;
]]]

