/* ── Page load animation ── */
/* No filter here on purpose: one non-compositable property forces the whole
   animation onto the main thread, where the cold-load template compile
   stalls it. transform+opacity only keeps it on the compositor. */
@keyframes casoraFadeIn {
  from { opacity: 0; transform: translateY(100px) scale(0.95); }
  to   { opacity: 1; transform: translateY(0)     scale(1);    }
}

@keyframes casoraFadeInRight {
  from { opacity: 0; transform: translateX(80px); }
  to   { opacity: 1; transform: translateX(0);    }
}

/* Desktop + tablet: slide in from right */
ha-card {
  animation: var(--casora-anim-name, casoraFadeInRight) var(--casora-anim-duration, 0.4s) var(--casora-ease-enter, cubic-bezier(0.16, 1, 0.3, 1)) both;
  animation-delay: var(--casora-anim-delay, var(--delay-d, 0s));
  animation-play-state: var(--casora-init-play, running);
  will-change: opacity, transform;
}

/* Mobile portrait: slide up from bottom */
@media (max-width: 767px) and (orientation: portrait) {
  ha-card {
    animation: var(--casora-anim-name, casoraFadeIn) var(--casora-anim-duration, 0.45s) var(--casora-ease-enter, cubic-bezier(0.16, 1, 0.3, 1)) both;
    animation-delay: var(--casora-anim-delay, var(--delay, 0s));
    animation-play-state: var(--casora-init-play, running);
  }
}

/* Progress */
#progress {
  background: none !important;
  mask: none !important;
  -webkit-mask: none !important;
  overflow: visible;
}

#progress svg {
  position: relative;
  z-index: 1;
}

#progress svg .casora-progress-glyph {
  fill: var(--casora-progress-arc-color, var(--casora-color-teal, #00c3d0));
  stroke: var(--casora-progress-arc-color, var(--casora-color-teal, #00c3d0));
}

#progress svg .casora-progress-track {
  stroke: var(--casora-progress-track-color, rgba(0,0,0,0.12));
}

#progress svg .casora-progress-arc {
  stroke: var(--casora-progress-arc-color, rgba(255,255,255,0.5));
  stroke-opacity: var(--casora-progress-arc-opacity, 1);
  stroke-dashoffset: calc(87.965px - var(--casora-progress-pct, 0) * 0.87965px);
  transition: stroke-dashoffset 0.8s linear;
}

/* Toggle tracks the tile unit, like the icon circle, so it stays proportional to the
   card. A fraction of the height, never height/200px: dividing a length by a length
   is CSS Values 4 and Firefox drops the whole declaration. On :host so it also
   reaches cards whose root element the ha-card selector does not match. */
:host {
  --casora-toggle-width: calc(var(--casora-entity-height-current, 200px) * 0.23);
  --casora-toggle-height: calc(var(--casora-entity-height-current, 200px) * 0.13);
