  --casora-box-shadow-mq: var(--casora-tile-rest-shadow-desktop, var(--casora-tile-glass-rim-desktop, var(--casora-tile-glass-rim, inset 0 1px 0 -0.5px rgba(255,255,255,0.10), 0 2px 8px rgba(0,0,0,0.10))));
  /* Sized off the icon circle: two balanced circles in opposite corners. Ratio, not a
     literal, so it tracks the card automatically. Visible ring is 32/36 of this (r14 +
     stroke 4 in a 36 viewBox), i.e. ~0.8x the icon circle. */
  --casora-progress-size-mq: calc(var(--casora-icon-circle-size, 44px) * var(--casora-progress-icon-ratio, 0.9));
  --casora-icon-circle-size: calc(var(--casora-entity-height-current, 200px) * var(--casora-icon-circle-ratio, 0.22));  /* casora_thermostat's temp puck reads this too */
  /* Every top-corner extra centers on this, so the toggle, the progress ring and
     the thermostat's rail stay in line with the icon circle at every tile size. */
  --casora-icon-center-y: calc(
    var(--casora-entity-inner-pad-current, var(--casora-entity-inner-pad-desktop, 20px))
    + var(--casora-tile-icon-mt, -2px)
    + var(--casora-icon-circle-size, 44px) / 2);
  --casora-entity-active-tint-current: var(--casora-entity-active-tint, rgba(255,255,255,0.94));
  --casora-icon-fallback-color: rgba(50,50,50,0.85);
