  --casora-tile-rows: var(--casora-tile-rows-mq);
  --casora-tile-gap: var(--casora-tile-gap-mq);
  --casora-tile-name-mb: var(--casora-tile-name-mb-mq);
  --casora-tile-align-content: var(--casora-tile-align-content-mq);
  --casora-tile-icon-align: var(--casora-tile-icon-align-mq);
  --casora-tile-icon-mt: var(--casora-tile-icon-mt-mq);
  --casora-tile-extras: var(--casora-tile-extras-mq);
  --casora-tile-radius: var(--casora-tile-radius-mq);
  --casora-tile-state-inset: var(--casora-tile-state-inset-mq);
