casora_weather.name:
[[[
let tempVal = null;

const tempEid = ((s) => { const _a = (s && s.attributes) || {}; const _u = String(_a.unit_of_measurement || ''); return !!s && (_a.device_class === 'temperature' || /°|^K$/.test(_u) || (!_u && !_a.device_class)); })(states[variables.weather_temp_sensor]) ? variables.weather_temp_sensor : null;
const w = entity;

if (tempEid) {
const tState = states[tempEid];
if (tState && !['unknown','unavailable',''].includes(String(tState.state))) {
const n = Number(tState.state);
if (!Number.isNaN(n)) tempVal = Math.round(n);
}
}

if (tempVal === null) {
const n = Number(w?.attributes?.temperature);
if (!Number.isNaN(n)) tempVal = Math.round(n);
}

if (variables?.hero_mode) {
if (tempVal === null) return '';

let iconHtml = '';
if (variables?.show_icon !== false) {
const condRaw = String(w?.state || '').toLowerCase();
const svgMap = {
'sunny':           'clear-day',
'clear-night':     'clear-night',
'partlycloudy':    'partly-cloudy-day',
'cloudy':          'cloudy',
'overcast':        'cloudy',
'rainy':           'rain',
'pouring':         'rain-heavy',
'snowy':           'snow',
'snow':            'snow',
'snowy-rainy':     'weather-mixed',
'hail':            'rain-heavy',
'lightning':       'thunder',
'lightning-rainy': 'lightning-rainy',
'fog':             'fog',
'windy':           'wind',
'windy-variant':   'wind',
'exceptional':     'weather-mixed'
};
let _wFill = false;
try { _wFill = getComputedStyle(document.documentElement).getPropertyValue('--casora-weather-glyph-fill').trim() === '1'; } catch (e) {}
const _hasFill = ['cloudy','partly-cloudy-day','clear-night','fog','rain','rain-heavy','snow','thunder','lightning-rainy','weather-mixed'];

const file = svgMap[condRaw];
if (file) {
iconHtml = `<img src="/casora_assets/weather/${file}${_wFill && _hasFill.includes(file) ? '-fill' : ''}.svg" style="width:auto;height:var(--weather-icon-size,34px);object-fit:contain;opacity:0.92;flex-shrink:0;filter:var(--casora-hero-weather-glyph-filter, none);" />`;
}
}

const _base = `<span style="position:relative;top:var(--weather-hero-digit-align, 3px);">${tempVal}°</span>${iconHtml}`;
let _wxDetail = false;
try { _wxDetail = getComputedStyle(document.documentElement).getPropertyValue('--casora-hero-weather-details').trim() === '1'; } catch (e) {}
const _hd = variables?.hero_details;
if (_hd === false || String(_hd) === 'false') _wxDetail = false;
if (!_wxDetail) {
return `<span style="display:inline-flex;align-items:center;gap:var(--casora-hero-weather-glyph-gap, 4px);">${_base}</span>`;
}

const _isMob = window.matchMedia('(max-width: 767px), (max-height: 600px)').matches;
const _dev = (!_isMob && window.matchMedia('(max-width: 1024px)').matches) ? 'tablet' : 'desktop';
const _ck = String(w?.state || '').toLowerCase().trim();
const _cm = {
'sunny': 'Sonnig', 'clear-night': 'Klare Nacht', 'partlycloudy': 'Teilweise bewölkt',
'cloudy': 'Bewölkt', 'overcast': 'Bedeckt', 'rainy': 'Regnerisch', 'pouring': 'Starkregen',
'snowy': 'Schneefall', 'snow': 'Schneefall', 'snowy-rainy': 'Schneeregen', 'hail': 'Hagel',
'lightning': 'Gewitter', 'lightning-rainy': 'Gewitter mit Regen', 'fog': 'Nebel',
'windy': 'Windig', 'windy-variant': 'Windig', 'exceptional': 'Außergewöhnlich'
};
const _cond = (!_ck || ['unknown', 'unavailable'].includes(_ck)) ? '' : (_cm[_ck] || '');

const _id = w?.entity_id || '';
const _cls = 'casora-wx-sub-' + _id.replace(/[^a-z0-9_]/gi, '_');
const _r0 = (x) => (x == null || x === '' || Number.isNaN(Number(x))) ? null : Math.round(Number(x));
const _sub = (fc) => {
const day0 = new Date(); day0.setHours(0, 0, 0, 0);
const f = (fc || []).find((x) => x && new Date(x.datetime).getTime() >= day0.getTime() - 43200000);
if (!f) return '';
const hi = _r0(f.temperature), lo = _r0(f.templow), pp = _r0(f.precipitation_probability);
const parts = [];
if (hi !== null) parts.push(`<span>H ${hi}°</span>`);
if (lo !== null) parts.push(`<span>T ${lo}°</span>`);
if (pp !== null) parts.push(`<span style="color:var(--casora-weather-precip, #64D2FF);">${pp} % Regen</span>`);
if (!parts.length) return '';
return `<span style="display:block;margin-top:var(--casora-hero-weather-line-gap, 2px);">${parts.join('<span> · </span>')}</span>`;
};
window._casoraWxDay = window._casoraWxDay || {};
const _C = window._casoraWxDay;
const _conn = hass && hass.connection;
const _daily = ((Number(w?.attributes?.supported_features) || 0) & 1) === 1;
const _now = Date.now();
if (_id && _daily && _conn && !(_C[_id] && (_C[_id].busy || _now - _C[_id].ts < 1800000))) {
_C[_id] = { fc: _C[_id] ? _C[_id].fc : null, ts: _now, busy: true };
let _un = null, _done = false;
const _stop = () => {
_done = true;
if (_un) { try { _un(); } catch (e) {} _un = null; }
if (_C[_id]) _C[_id].busy = false;
};
_conn.subscribeMessage((msg) => {
if (_done) return;
_C[_id] = { fc: (msg && msg.forecast) || [], ts: Date.now(), busy: true };
try {
let html = _sub(_C[_id].fc);
if (window.casoraTr) html = window.casoraTr(html);
const ha = document.querySelector('home-assistant');
const walk = (n) => {
if (!n || !n.querySelectorAll) return;
n.querySelectorAll('.' + _cls).forEach((el) => { el.innerHTML = html; });
n.querySelectorAll('*').forEach((x) => { if (x.shadowRoot) walk(x.shadowRoot); });
};
walk((ha && ha.shadowRoot) || document);
} catch (e) {}
_stop();
}, { type: 'weather/subscribe_forecast', forecast_type: 'daily', entity_id: _id })
.then((u) => { _un = u; if (_done) { try { u(); } catch (e) {} _un = null; } })
.catch(() => { _C[_id] = { fc: [], ts: Date.now(), busy: false }; _done = true; });
setTimeout(() => { if (!_done) _stop(); }, 60000);
}
const _subHtml = _C[_id] && _C[_id].fc ? _sub(_C[_id].fc) : '';

return `<span style="display:inline-flex;align-items:center;gap:var(--casora-hero-weather-text-gap-${_dev}, 9px);">`
+ `<span style="display:inline-flex;align-items:center;gap:var(--casora-hero-weather-glyph-gap, 4px);">${_base}</span>`
+ `<span style="display:flex;flex-direction:column;text-align:left;line-height:1.15;letter-spacing:0;">`
+ (_cond ? `<span style="font-size:var(--casora-hero-weather-cond-size-${_dev}, 14px);font-weight:600;">${_cond}</span>` : '')
+ `<span class="${_cls}" style="font-size:var(--casora-hero-weather-sub-size-${_dev}, 12px);font-weight:500;color:var(--casora-text-2, var(--secondary-text-color));">${_subHtml}</span>`
+ `</span></span>`;
}

return (tempVal === null) ? '' : `${tempVal}°`;
]]]

