const tsId = variables.weather_temp_sensor && ((s) => { const _a = (s && s.attributes) || {}; const _u = String(_a.unit_of_measurement || ''); return !!s && (_a.device_class === 'temperature' || /°|^K$/.test(_u) || (!_u && !_a.device_class)); })(states[variables.weather_temp_sensor]) ? variables.weather_temp_sensor : null;
