const v = parseFloat(entity?.state);
let label = 'Unbekannt';
if (!isNaN(v)) {
if (v <= 29.99)   label = 'Sehr trocken';
else if (v >= 61) label = 'Hoch';
else              label = 'Gut';
}

const esc = (t) => String(t || '').replaceAll('"','&quot;');
const vStr = !isNaN(v) ? ` · ${Math.round(v)}%` : '';

return `
    <div class="badge-wrap">
      <div class="badge-title">Luftfeuchtigkeit</div>
      <div class="badge-sub">${esc(label)}${vStr}</div>
    </div>
  `;
]]]

card.display:
[[[
