casora_badge_media.extra_styles:
ha-ripple,
mwc-ripple {
  display: none !important;
}

/* Entity artwork rim */
#img-cell::before{
  content:"";
  position:absolute;
  inset:0;
  border-radius:24%;
  pointer-events:none;
  z-index:7;
  box-shadow:
    inset 0 0 0 var(--casora-badge-art-ring-width, 0.5px) rgba(255,255,255,var(--casora-badge-art-ring-line, 0.12));
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

/* Rim */
:host{
  position: relative !important;
  --casora-badge-hold: calc((1 - var(--casora-badge-opacity, 1)) * 0.75s);
  --casora-media-badge-pad-v: 0px;
}

/* Tablet (touch, 768-1400px) - matches the group badges' vertical padding
   (see --badge-padding-current in casora_badge_base.yaml). */
@media (min-width: 768px) and (max-width: 1400px) and (min-height: 501px) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1400px) and (min-height: 501px) and (hover: none) {
  :host{
    --casora-media-badge-pad-v: var(--badge-media-pad-v-tablet, 7px);
  }
}

:host::after{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  border-radius: var(--casora-media-badge-br, 9999px);

  --casora-rim-side:      var(--casora-badge-rim-side-blur, 2px) var(--casora-badge-rim-side-spread, -1px) rgba(0,0,0,var(--casora-badge-rim-side, 0.98));
  --casora-rim-bottom:    0 1px 1px -1px rgba(0,0,0,var(--casora-badge-rim-bottom, 0.14));
  --casora-rim-top:       0 -1px 1px -1px rgba(0,0,0,var(--casora-badge-rim-top, 0.12));
  --casora-rim-elevation: 0 2px 8px rgba(0,0,0,var(--casora-badge-elevation, 0.22));

  box-shadow:
    var(--casora-badge-rim-side-offset, 1px) 0 var(--casora-rim-side),
    calc(-1 * var(--casora-badge-rim-side-offset, 1px)) 0 var(--casora-rim-side),
    var(--casora-rim-bottom),
    var(--casora-rim-top),
    var(--casora-rim-elevation);

  --casora-rim-delay: calc(var(--casora-badge-enter-delay, 0ms) * var(--casora-badge-enter-t));

  opacity: calc(var(--casora-badge-has-art, 1) * (1 - var(--casora-badge-enter-p))
           * var(--casora-row-fade, 1));

  transform-origin: var(--casora-badge-enter-origin);
  transform: var(--casora-badge-enter-transform);
  -webkit-transform: var(--casora-badge-enter-transform);
  translate: var(--casora-badge-flip-x, 0px);
  transition: transform var(--casora-badge-enter-dur) var(--casora-badge-enter-ease, cubic-bezier(0.34, 1.26, 0.44, 1)) var(--casora-rim-delay),
              translate var(--casora-badge-flip-dur, 0.42s)
                        var(--casora-badge-flip-ease, cubic-bezier(0.32, 0.72, 0, 1)),
              opacity var(--casora-badge-enter-fade) ease var(--casora-rim-delay);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

/* Mobile rim */
@media (max-width: 767px) and (orientation: portrait),
       (max-height: 600px) and (orientation: landscape) {
  :host::after{
    --casora-badge-rim-side: 0.95;
    --casora-badge-rim-side-offset: 1px;
    --casora-badge-rim-side-blur: 0px;
    --casora-badge-rim-side-spread: -.3px;
    --casora-badge-rim-top: 0;
    --casora-badge-rim-bottom: 0;
    --casora-badge-elevation: 0;
  }
}

/* Hover Override */
:host ha-card{
  box-shadow: none !important;
  transform-origin: var(--casora-badge-enter-origin) !important;
  transform: var(--casora-badge-enter-transform) !important;
  --casora-badge-enter-delay: inherit !important;
  --button-card-box-shadow-hover: none;
  --button-card-box-shadow-active: none;
