}

:host ha-card:not(#casora-badge-shadow-suppress):active #container::after{
  opacity: 0.12;
}

/* Background Image */
:host ha-card::after{
  content:"";
  position:absolute;
  inset: -30px;
  pointer-events:none;
  background:
    linear-gradient(rgba(0,0,0,0.20), rgba(0,0,0,0.20)),
    var(--bg-url),
    linear-gradient(var(--casora-badge-art-floor, rgba(160,160,160,0.28)) 0 0);
  background-blend-mode: normal, lighten;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  filter: blur(24px) saturate(1.6);
  opacity: var(--casora-badge-has-art, 1);
  transform: scale(1.25);
}

/* Specular ring */
:host ha-card::before{
  content:"";
  position:absolute;
  inset: 0px;
  pointer-events:none;
  border-radius: inherit;
  padding: var(--casora-badge-ring-thickness, 1.3px);
  backdrop-filter: var(--casora-badge-ring-backdrop, brightness(var(--casora-badge-ring-boost, 1.5)) saturate(var(--casora-badge-ring-sat, 1.8)));
  -webkit-backdrop-filter: var(--casora-badge-ring-backdrop, brightness(var(--casora-badge-ring-boost, 1.5)) saturate(var(--casora-badge-ring-sat, 1.8)));
  mix-blend-mode: screen;
  -webkit-mask:
    linear-gradient(to bottom,
      rgba(0,0,0,.5) 0%,
      rgba(0,0,0,0.15) 32%,
      rgba(0,0,0,0) 45%,
      rgba(0,0,0,0) 55%,
      rgba(0,0,0,0.07) 68%,
      rgba(0,0,0,0.05) 100%),
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: source-in, xor;
          mask-composite: intersect, exclude;
  opacity: var(--casora-badge-has-art, 1) !important;
  transform: translateZ(0);
  -webkit-transform: translateZ(0);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
}

