casora_badge_temp.name:
[[[
const v    = parseFloat(entity?.state);
const unit = String(variables?.temp_unit || (hass.config?.unit_system?.temperature === '°F' ? 'F' : 'C')).toUpperCase();
if (isNaN(v)) return '';

const t = (unit === 'F')
? { veryCold: 65, cool: 70, comfortable: 76, warm: 81, hot: 85 }
: { veryCold: 18, cool: 21, comfortable: 24, warm: 27, hot: 29 };

let label = 'Unbekannt';
if      (v <= t.veryCold)    label = 'Sehr kalt';
else if (v <= t.cool)        label = 'Kühl';
else if (v <= t.comfortable) label = 'Angenehm';
else if (v <= t.warm)        label = 'Warm';
else if (v <= t.hot)         label = 'Heiß';
else                         label = 'Sehr heiß';

const dispVal = `${Math.round(v)}°`;
const esc = (s) => String(s || '').replaceAll('"', '&quot;');

return `
    <div class="badge-wrap">
      <div class="badge-title">Temperatur</div>
      <div class="badge-sub">${esc(label)} · ${dispVal}</div>
    </div>
  `;
]]]

