casora_mobile_chrome.extra_styles:
/* ha-card is overflow:visible so the count can sit proud of the circle,
   which also stopped it clipping button-card's ripple - a square layer
   filling the card's box, so the hover read as a box behind the disc. */
:host{
  --button-card-ripple-color: transparent !important;
  --button-card-ripple-hover-color: transparent !important;
  --ha-ripple-color: transparent !important;
  --ha-ripple-hover-color: transparent !important;
  --mdc-ripple-press-opacity: 0 !important;
}
:host ha-ripple,
:host mwc-ripple{ display: none !important; }
:host{
  display: block !important;
  pointer-events: auto !important;
}

/* Measured off iOS's own capsule. Three layers, none on ha-card, which HA and
   the theme restyle: the glass, the content, then the edge light, which
   brightens the glass behind it rather than painting white over it. */
:host{
  --casora-card-hover-filter: none;
  --casora-hover-filter: none;
}
:host ha-card{
  position: relative !important;
  border-radius: calc(var(--casora-mchrome-h, 44px) / 2) !important;
  background: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  filter: none !important;
  border: none !important;
  overflow: visible !important;
  isolation: isolate;
}
:host ha-card::before{
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  border-radius: inherit;
  background-color: var(--casora-pill-fill, rgba(255,255,255,0.10));
  backdrop-filter: var(--casora-pill-backdrop, blur(12px) saturate(1.4));
  -webkit-backdrop-filter: var(--casora-pill-backdrop, blur(12px) saturate(1.4));
  box-shadow: var(--casora-pill-rim, inset 0 0.5px 0 rgba(255,255,255,0.10), inset 0 -0.5px 0 rgba(255,255,255,0.10)),
    -0.5px 0 0 var(--casora-pill-edge, rgba(0,0,0,0.50)), 0.5px 0 0 var(--casora-pill-edge, rgba(0,0,0,0.50));
  pointer-events: none;
}
:host ha-card::after{
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  border-radius: inherit;
  backdrop-filter: var(--casora-pill-highlight, brightness(1.45));
  -webkit-backdrop-filter: var(--casora-pill-highlight, brightness(1.45));
  padding: 1px;
  box-sizing: border-box;
  -webkit-mask: linear-gradient(to bottom, #000 0, rgba(0,0,0,.45) 13%, transparent 31%, transparent 69%, rgba(0,0,0,.45) 87%, #000 100%), linear-gradient(#000 0 0), linear-gradient(#000 0 0) content-box;
  -webkit-mask-composite: source-in, source-out;
  mask: linear-gradient(to bottom, #000 0, rgba(0,0,0,.45) 13%, transparent 31%, transparent 69%, rgba(0,0,0,.45) 87%, #000 100%), linear-gradient(#000 0 0), linear-gradient(#000 0 0) content-box;
  mask-composite: intersect, subtract;
  pointer-events: none;
}

/* A filled button is flat. The capsule carries the glass; a button lit
   white on top of it should read as one solid shape, not as a disc with
   the capsule's sheen and blur showing through its edge. */
:host ha-card > .custom-field ha-card,
:host ha-card button-card{
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  background-image: none !important;
}

:host #edit::before{
  content: "";
  display: var(--casora-chrome-sep, none);
  position: absolute;
  left: -2.5px;
  top: var(--casora-chrome-sep-top, 13px);
  width: 1px;
  height: var(--casora-chrome-sep-h, 18px);
  background: var(--casora-pill-divider, rgba(60,60,67,0.36));
  pointer-events: none;
}

/* The badge hangs outside the capsule, so nothing on the way may clip. */
:host #container,
:host .button-card-content,
:host #customfields,
:host .custom-field,
:host .vertical,
:host .ellipsis{ overflow: visible !important; }

/* Handy-Leiste B (1.3): sitzt die Kapsel in der unteren Navigationsleiste, setzt casora-mobile-nav
   dort die --casora-mchrome-*-Werte: kein eigenes Glas, Tasten 50 breit mit Sand-Kreis 36 wie
   die Leisten-Tasten, kein innerer Trenner (die Leiste hat ihren eigenen vor der Glocke). */
:host ha-card::before,
:host ha-card::after{ display: var(--casora-mchrome-glass, block); }
:host #bell,
:host #assist,
:host #edit{ padding: 0 var(--casora-mchrome-slot-pad, 0px) !important; }
:host #edit::before{ visibility: var(--casora-mchrome-sep-vis, visible); }

