  top: -200px !important;
  z-index: 100 !important;
  display: block !important;
}
:host(.casora-navbar-card.casora-navbar-card):active {
  filter: none !important;
  -webkit-filter: none !important;
}
:host { filter: none !important; -webkit-filter: none !important; }
ha-card.button-card-main {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  border: none !important;
  overflow: visible !important;
  padding: 0 !important;
  contain: none !important;
  isolation: auto !important;
  will-change: auto !important;
  transition: none !important;
  filter: none !important;
  -webkit-filter: none !important;
}
.button-card-main, .button-card-content, #customfields {
  overflow: visible !important;
  contain: none !important;
  isolation: auto !important;
}

/* Handy: zu breite Badge-Reihen blättern seitwärts (30.09.2026). Die innere Karte ist so breit
   wie ihre Badges (mindestens die Reihe), damit die Reihe selbst scrollt und nicht das Raster
   darin über den Rand ragt. Der rechte Abstand sitzt an der inneren Karte, sonst fehlt er
   am Ende des Scrollbereichs. Weiche Ränder setzt window._casoraBadgeRows (01-basis.js). */
#badges > *{width:max-content!important;min-width:100%!important;display:block!important;box-sizing:border-box!important;padding-right:var(--casora-rail-left, 16px)!important}
#badges::-webkit-scrollbar{display:none!important}
#badges{touch-action:pan-x pan-y;-webkit-overflow-scrolling:touch}
#badges[data-cs-fade="r"]{-webkit-mask-image:linear-gradient(to right,#000 calc(100% - 32px),transparent);mask-image:linear-gradient(to right,#000 calc(100% - 32px),transparent)}
#badges[data-cs-fade="l"]{-webkit-mask-image:linear-gradient(to right,transparent,#000 32px);mask-image:linear-gradient(to right,transparent,#000 32px)}
#badges[data-cs-fade="l r"]{-webkit-mask-image:linear-gradient(to right,transparent,#000 32px,#000 calc(100% - 32px),transparent);mask-image:linear-gradient(to right,transparent,#000 32px,#000 calc(100% - 32px),transparent)}

