card.extra_styles:
[[[
const staticCSS = `:host(.casora-navbar-card.casora-navbar-card):active{filter:none!important;-webkit-filter:none!important}:host{filter:none!important;-webkit-filter:none!important;touch-action:pan-x!important}ha-card.button-card-main{will-change:auto!important;isolation:auto!important;contain:none!important;transition:none!important;touch-action:pan-x!important}.button-card-main,.button-card-content,#customfields{touch-action:pan-x!important}#media1 > *,#media2 > *,#media3 > *,#media4 > *,#media5 > *,#media6 > *,#media7 > *,#media8 > *,#media9 > *{width:100%!important;min-width:100%!important;max-width:100%!important;flex:1 1 auto!important}`;

const flipIds = ['media1','media2','media3','media4','media5','media6','media7','media8','media9'];
const filter = states['input_select.casora_mobile_filter']?.state ?? 'all';
const inColumn = filter === 'media';

const wantColumn = inColumn;
