}

if (window._casoraNPDebug === true) try {
const W = window;
W._casoraNPProbe = W._casoraNPProbe || { n: 0, last: 0, uid: 0 };
const P = W._casoraNPProbe;
P.n += 1;
const now = Date.now();
const dt = P.last ? (now - P.last) : 0;
P.last = now;

const dig = (root, depth, path) => {
if (!root || depth > 5) return null;
if (root.getElementById && root.getElementById('media1')) return { root: root, path: path };
const kids = root.querySelectorAll ? root.querySelectorAll('*') : [];
for (const k of kids) {
if (k.shadowRoot) {
const r = dig(k.shadowRoot, depth + 1, path + ' > ' + k.tagName.toLowerCase());
