: null;
const disp = wrap.style.display || getComputedStyle(wrap).display;
if (!slot && !hold && disp === 'none') continue;
rows.push('    ' + id +
'  slot=' + (slot || '-') +
(exitSlots[i] ? '(EXITING)' : '') +
(entering[i] ? '(OPENING)' : '') +
(slotSnapped[id] ? '(SNAP)' : '') +
'  rank=' + (live || '-') +
'  hold=' + (hold || '-') +
'  wrap=' + idOf(wrap) +
