casora_mobile_weather.extra_styles:
@keyframes titleFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to   { opacity: 0.9; transform: translateY(0); }
}
#name { animation: titleFadeIn 0.3s ease-out both; }
ha-card.button-card-main {
  align-items: stretch !important;
  justify-content: flex-start !important;
  text-align: left !important;
}
#container, .button-card-content { width: 100% !important; }
#name { justify-self: start !important; }

casora_mobile_weather.name:
[[[
const f = states['input_select.casora_mobile_filter']?.state ?? 'all';
if (f === 'all') {
const own = String(variables.home_name || '').trim();
const r = window.casoraRoomName ? window.casoraRoomName(own || 'Home',
{ casora_auto_name: !own && variables.home_auto === true ? 'home' : undefined, name_literal: !!own || variables.name_literal === true }) : null;
const text = r ? r.text : (own || 'Home');
const lit = r ? r.literal : (variables.name_literal === true && !!own);
if (!lit) return text;
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return '<span data-no-i18n>' + esc(text) + '</span>';
}
const labels = {climate:'Klima',lights:'Beleuchtung',presence:'Personen',media:'Medien',security:'Sicherheit',energy:'Energie'};
return labels[f] || 'Zuhause';
]]]

card.--casora-name-literal:
[[[
