{ casora_auto_name: !own && variables.home_auto === true ? 'home' : undefined, name_literal: !!own || variables.name_literal === true }) : null;
const lit = f === 'all' && (r ? r.literal : (variables.name_literal === true && !!own));
const n = this.shadowRoot && this.shadowRoot.getElementById('name');
if (n) {
if (lit) {
n.setAttribute('data-no-i18n', '');
const want = r ? r.text : own;
const tn = n.textContent !== want && Array.from(n.childNodes).find((c) => c.nodeType === 3 && c.data.trim());
if (tn) tn.data = want;
} else n.removeAttribute('data-no-i18n');
