custom_fields.ring:
[[[
if (!variables.ring || !variables.src?.controls?.toggle) return '';
const s = variables.src;
const SW = 2.2;
const R = 20 - (SW / 2) - 0.5;
const C = 2 * Math.PI * R;

const st = String(s.state || '').toLowerCase();
const trackable = st === 'playing' || st === 'buffering' || st === 'paused';

let arc = '';
if (trackable && Number.isFinite(s.dur) && s.dur > 0 && Number.isFinite(s.pos)) {
const elapsed = s.playing && s.posAt ? (Date.now() - s.posAt) / 1000 : 0;
const now = Math.min(s.dur, Math.max(0, s.pos + elapsed));
const frac = Math.max(0, Math.min(1, now / s.dur));
const remain = Math.max(0, s.dur - now);
const anim = s.playing && remain > 0
? `animation: np-ring-advance ${remain.toFixed(1)}s linear forwards;`
: '';
if (s.playing || now > 1) {
arc = `
        <circle class="np-ring-track" cx="20" cy="20" r="${R.toFixed(3)}"></circle>
        <circle class="np-ring-fill" cx="20" cy="20" r="${R.toFixed(3)}"
          transform="rotate(-90 20 20)"
          style="stroke-dasharray: ${C.toFixed(3)}; stroke-dashoffset: ${(C * (1 - frac)).toFixed(3)}; ${anim}"></circle>
      `;
}
}

return `
    <svg class="np-ring" viewBox="0 0 40 40" aria-hidden="true">
      <circle class="np-ring-disc" cx="20" cy="20" r="${(R - (SW / 2)).toFixed(3)}"></circle>
      ${arc}
    </svg>
  `;
]]]

casora_now_playing_controls.extra_styles:
[[[
const c = variables.src?.controls;
const any = variables.only_toggle
? !!c?.toggle
: !!(c && (c.toggle || c.next || c.prev));
return `
    :host{
      display: ${any ? 'block' : 'none'} !important;
      --casora-card-hover-shadow: none;
      --casora-card-hover-filter: none;
    }
    :host, ha-card{
      background: none !important;
      box-shadow: none !important;
      border: none !important;
      backdrop-filter: none !important;
      -webkit-backdrop-filter: none !important;
    }

    /* Containing block for the ring overlay. overflow must stay visible: #container measures
       smaller than the 40px ring box in at least one axis, and the default clip flattened the
       circle's top, bottom and right edges. */
    #container{
      position: relative !important;
      overflow: visible !important;
    }

    .np-ring{
      display: block;
      width: 100%;
      height: 100%;
      overflow: visible;
    }

    .np-ring-disc{
      fill: var(--casora-np-ring-disc, rgba(255,255,255,var(--np-ring-disc-alpha, 0.16)));
    }

    .np-ring-track{
      fill: none;
      stroke: var(--casora-np-ring-track, rgba(255,255,255,var(--np-ring-track-alpha, 0.22)));
      stroke-width: 2.2;
    }

    .np-ring-fill{
      fill: none;
      stroke: var(--casora-np-ring-fill, rgba(255,255,255,var(--np-ring-fill-alpha, 0.95)));
      stroke-width: 2.2;
      stroke-linecap: round;
    }

    @keyframes np-ring-advance{ to { stroke-dashoffset: 0; } }

    @media (prefers-reduced-motion: reduce){
      .np-ring-fill{ animation: none !important; }
    }
  `;
]]]

