if (v <= t.good) return 0;
if (v <= t.moderate) return 1;
if (v <= t.high) return 2;
return 3;
});
switch (Math.max(..._levels)) {
case 0: scoreLabel='Ausgezeichnet'; advice='Luftqualität ist hervorragend';  score=5; break;
case 1: scoreLabel='Mäßig';  advice='Luftqualität ist mäßig'; score=3; break;
