const makeFilterPills = (rooms, delayMs) => {
const _n  = rooms.length;
const _gk = JSON.stringify(groupId);

const pillsInitSnip = `
            window._casoraLPR_pills = window._casoraLPR_pills || {};
            window._casoraLPR_pills[${_gk}] = this.shadowRoot;
            /* The popup dismisses on a background tap, and its listener is
               a click on .content - an ancestor of this row. Reading the
               tap back out of the composed path was unreliable: the pill's
               own card re-renders on tap, so what the path holds by then
               is not what was on screen when it was pressed. The row says
               so directly instead. Bubble phase only, and click only - the
               action handler is a body-level singleton working off pointer
               events, and swallowing those leaves a stuck hold circle. */
            this.setAttribute('data-casora-nodismiss', '');
            /* The shift is a REFLOW, not an animation. Every pill is a
               nested button-card that lays out a beat after the row does,
               and the row is centered - so each pill that arrives at its
               real width pushes the center left and drags the ones
               already painted with it. Nothing eases because nothing is
               animating; you are watching layout settle.
               Held invisible until it has, then the entrance plays. */
            /* styles.card re-stamps visibility:hidden on EVERY render, so
               the reveal has to run every time too - guarding it with the
               intro flag meant toggling a light re-rendered the row and
               nothing ever brought it back. Only the entrance animation
               is once. ha-card is usually not in the shadow root yet when
               this field evaluates, so wait for it. */
            {
              const _first = !this._casoraPillIntro;
              this._casoraPillIntro = true;
              if (_first) this._casoraPillT0 = performance.now();
              const _self = this;
              /* One loop at a time. Every render started another, and the
                 row re-renders on every brightness change. */
              if (_self._casoraPillRaf) cancelAnimationFrame(_self._casoraPillRaf);
              if (_self._casoraPillNet) clearTimeout(_self._casoraPillNet);
              const _show = function (pc) {
                if (_first) {
                  /* Restart the entrance BEFORE revealing it, or the row
                     paints at full opacity for a frame and the animation
                     takes it back to zero. Resumed at the phase it would
                     have reached rather than from zero: the row is
                     invisible while it settles, and replaying the whole
                     320ms afterwards is what put the pills a beat behind
                     the close control. Longhands only - the animation
                     shorthand would drop the delay with it. */
                  const _t0 = _self._casoraPillT0;
                  const _el = _t0 ? Math.min(Math.round(performance.now() - _t0), 320) : 0;
                  pc.style.animationName = 'none';
                  void pc.offsetWidth;
                  pc.style.animationDelay = '-' + _el + 'ms';
                  pc.style.animationName = '';
                }
