const tileThresh = (val, maxScale) => {
if (val == null) {
return { label: '—', color: 'rgba(255,255,255,0.4)', pct: 0 };
}

let pct;
if (val < 1) {
pct = val * 15;
} else if (val < 10) {
pct = 15 + ((val - 1) / 9) * 25;
} else if (val < 50) {
pct = 40 + ((val - 10) / 40) * 30;
} else {
pct = Math.min(100, 70 + ((val - 50) / Math.max(1, maxScale - 50)) * 30);
}

if (val < 1) {
return { label: 'Inaktiv', color: 'var(--casora-badge-network-idle-color, rgba(255,255,255,0.90))', pct };
}
if (val < 10) {
return { label: 'Gering', color: 'var(--casora-badge-network-low-color, #44e371)', pct };
}
if (val < 50) {
return { label: 'Aktiv', color: 'var(--casora-badge-network-active-color, #ffd600)', pct };
}
return { label: 'Hoch', color: 'var(--casora-badge-network-high-color, #ff9230)', pct };
};

