popup_styles.styles:
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
/* The totals read as one line when the label is a hair from the
   number - "This month" was touching "36 kWh". */
--casora-popup-value-gap-wide: 28px;
--casora-popup-gutter-wide: 34px;
--casora-popup-gutter-phone: 22px;

/* Held. A chart has to fetch its history, so revealing the widgets
   first only meant watching the graph arrive late. casora-popup
   stamps data-casora-charts-ready once every chart in the popup has
   drawn, or gives up on one that never will, and the entry below
   swaps the hold for the entrance. Read by each widget for itself,
   never by a wrapper. */
--casora-popup-plate-enter: casora-plate-hold 10s linear both;

/* Wide enough for the aside. .surface already caps itself at
   calc(100vw - 16px), so a narrow screen shrinks rather than
   overflows, and the grid collapses to one column under 760px. */
--popup-min-width: 900px;
--popup-max-width: 920px;
--casora-popup-aside-w: 300px;

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;

--casora-popup-row-pad-x: 26px;
--casora-popup-row-pad-y: 15px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none);
  box-shadow: var(--casora-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

/* Popup-Standard (24.09.2026): Info-Popup - Abschnittsüberschriften in der Karte. */
--casora-lbl-in: block;
--casora-lbl-out: none;

casora_popup.content:
[[[
const plant      = entity?.entity_id;
const _plantName = plant ? plant.replace(/^[^.]+\./, '') : '';
const plantAttrs = states[plant]?.attributes || {};
const _PLANT_DC = ['moisture', 'temperature', 'illuminance', 'conductivity', 'humidity', 'battery'];
const sensors    = (() => {
const own = (Array.isArray(variables.sensors) ? variables.sensors.filter(Boolean) : [])
.filter((id) => { const dc = String(states[id]?.attributes?.device_class || ''); return !dc || _PLANT_DC.includes(dc); });
if (own.length) return own;
const reg = hass?.entities || {};
const dev = plant && reg[plant]?.device_id;
if (!dev) return [];
return Object.keys(reg).filter((id) => id.startsWith('sensor.') && reg[id].device_id === dev && !reg[id].hidden
&& states[id] && _PLANT_DC.includes(String(states[id].attributes?.device_class || '')))
.sort((a, b) => _PLANT_DC.indexOf(states[a].attributes.device_class) - _PLANT_DC.indexOf(states[b].attributes.device_class));
})();

const _ck = 'casora_plant_v8_' + (window._casoraSoft && window._casoraSoft() ? 'w_' : '') + (plant || 'x');
const _ch = [variables.room_name || '', String(this?._config?.name || ''), states[plant]?.state, JSON.stringify(states[plant]?.attributes), ...sensors.map(s => states[s]?.state)].join('|');
window._hc = window._hc || {};
if (window._hc[_ck]?.h === _ch) { if (window._hcChart?.[_ck] && typeof window._hpChartInit === 'function') window._hpChartInit(window._hcChart[_ck]); return window._hc[_ck].r; }

const safeNum = (id) => {
if (!id) return null;
const s = states[id]?.state;
if (!s || s === 'unavailable' || s === 'unknown') return null;
const n = parseFloat(s);
return isNaN(n) ? null : n;
};

const getSensorType = (eid) => {
const id = eid.toLowerCase();
if (id.includes('moisture') || id.includes('bodenfeuchtigkeit')) return 'moisture';
if (id.includes('illumin') || id.includes('lux') || id.includes('beleuchtungsstarke') || id.includes('helligkeit')) return 'illuminance';
if (id.includes('temp'))                           return 'temperature';
if (id.includes('conductiv') || id.includes('leitfahigkeit') || id.includes('naehrstoff') || id.includes('nahrstoff')) return 'conductivity';
if (id.includes('humid') || id.includes('luftfeuchtigkeit')) return 'humidity';
if (id.includes('battery') || id.includes('batterie')) return 'battery';
const dc = String(states[eid]?.attributes?.device_class || '');
return _PLANT_DC.includes(dc) ? dc : null;
};

const getThreshold = (type, dir) => {
if (!type || type === 'battery' || !_plantName) return null;
const slug = type === 'moisture' ? 'soil_moisture'
: type === 'humidity' ? 'air_humidity'
: type;
const v = safeNum(`number.${_plantName}_${dir}_${slug}`);
return v !== null ? v : safeNum(`number.${_plantName}_${dir}_${type}`);
};

const plantState = states[plant]?.state;
const plantIsOk  = plantState === 'ok';
const plantIsBad = plantState === 'problem';

const gradable = sensors.filter(s => {
const t = getSensorType(s);
return t && t !== 'battery';
});
const readable = gradable.filter(s => safeNum(s) != null);


const _PLANT_SAY = {
'moisture:low': 'Braucht Wasser', 'moisture:high': 'Steht zu nass',
'temperature:low': 'Steht zu kalt', 'temperature:high': 'Steht zu warm',
'soil_temperature:low': 'Steht zu kalt', 'soil_temperature:high': 'Steht zu warm',
'illuminance:low': 'Braucht mehr Licht', 'illuminance:high': 'Zu viel Sonne',
'dli:low': 'Braucht mehr Licht', 'dli:high': 'Zu viel Sonne',
'conductivity:low': 'Braucht Dünger', 'conductivity:high': 'Überdüngt',
'humidity:low': 'Luft zu trocken', 'humidity:high': 'Luft zu feucht',
'vpd:high': 'Luft zu trocken', 'vpd:low': 'Luft zu feucht',
};
const _PLANT_ORDER = ['moisture', 'temperature', 'soil_temperature', 'illuminance', 'dli', 'conductivity', 'humidity', 'vpd'];
const _plantBad = (attrs) => {
const out = {};
let list = attrs.problems;
if (typeof list === 'string') {
const re = /'sensor_type':\s*'(\w+)'[^}]*?'status':\s*'(\w+)'/g;
let m; list = [];
while ((m = re.exec(attrs.problems))) list.push({ sensor_type: m[1], status: m[2] });
}
(Array.isArray(list) ? list : []).forEach(p => {
if (p && p.sensor_type) out[p.sensor_type] = String(p.status || '').toLowerCase();
});
if (!Object.keys(out).length) _PLANT_ORDER.forEach(t => {
const v = attrs[t + '_status'];
if (v && v !== 'ok' && v !== 'null') out[t] = String(v).toLowerCase();
});
return out;
};
const _plantSay = (bad) => {
for (const t of _PLANT_ORDER) { const s = _PLANT_SAY[t + ':' + bad[t]]; if (s) return s; }
return null;
};

const badTypes = plantIsBad ? _plantBad(plantAttrs) : {};
const flagged = (t) => !!t && !!(badTypes[t] || (t === 'illuminance' && badTypes.dli));

const blind = !plantIsOk && !Object.keys(badTypes).length
&& !_PLANT_ORDER.some(t => plantAttrs[t + '_status'] != null && plantAttrs[t + '_status'] !== 'null');

const C_HEALTHY    = 'var(--casora-badge-plant-healthy-color, #44e371)';
const C_STRUGGLING = 'var(--casora-badge-plant-struggling-color, #ff9230)';

let advice;
if (plantIsOk) advice = 'Fühlt sich wohl';
else if (plantIsBad) advice = _plantSay(badTypes) || ((gradable.length && !readable.length) ? 'Keine Messwerte' : 'Bitte nachsehen');
else if (!plantState || plantState === 'unavailable') advice = 'Nicht verfügbar';
else advice = 'Wartet auf Daten';

const cleanName = (eid) => {
const fallback = states[eid]?.attributes?.friendly_name || eid.split('.').pop() || '';
const fold = (s) => Array.from(String(s || '')).map((ch) => (ch.normalize('NFD').charAt(0) || ch).toLowerCase()).join('');
const reg = hass?.entities || {}, devs = hass?.devices || {};
const devName = (id) => { const d = id && reg[id]?.device_id && devs[reg[id].device_id]; return d ? (d.name_by_user || d.name || '') : ''; };
const pres = [entity?.attributes?.friendly_name, devName(eid), devName(plant)]
.map((s) => String(s || '').trim()).filter(Boolean).sort((a, b) => b.length - a.length);
let name = Array.from(String(fallback).trim());
for (const pre of pres) {
const p = Array.from(pre), head = name.slice(0, p.length).join('');
if (name.length > p.length && /\s/.test(name[p.length]) && fold(head) === fold(pre)) { name = name.slice(p.length); break; }
}
let out = name.join('').replace(/_/g, ' ').trim();
out = out.replace(/^\d\s+(?=\D)/, '').replace(/(\D)\s+\d$/, '$1').trim() || String(fallback);
return out.replace(/(^|\s)(\S)(\S*)/g, (m, s, a, b) => s + a.toUpperCase() + b.toLowerCase());
};

const wrapperStyle = `
    :host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }
    ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: default !important; }
