const tileTapStyle = `
    :host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: inset 0 1px 0.5px -0.5px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-top-tight,0.20) * 1.5)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-bottom-tight,0.15) * 1.5)), inset 0 3px 6px -3px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-top-soft,0.08) * 1.5)), inset 0 -3px 6px -3px rgba(255,255,255,calc(var(--casora-popup-tiles-glow-bottom-soft,0.05) * 1.5)) !important; }
    ha-card { background: var(--casora-popup-tiles-fill, rgba(255,255,255,0.08)) !important; border: none !important; border-radius: 24px !important; box-shadow: inset 0 1px 0.5px -0.5px rgba(255,255,255,var(--casora-popup-tiles-glow-top-tight,0.20)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,var(--casora-popup-tiles-glow-bottom-tight,0.15)), inset 0 3px 6px -3px rgba(255,255,255,var(--casora-popup-tiles-glow-top-soft,0.08)), inset 0 -3px 6px -3px rgba(255,255,255,var(--casora-popup-tiles-glow-bottom-soft,0.05)) !important; backdrop-filter: var(--casora-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; -webkit-backdrop-filter: var(--casora-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; cursor: pointer !important; transform: scale(1) !important; transition: background-color var(--casora-popup-tile-hover-duration, 0.2s) ease, transform var(--casora-popup-tile-hover-duration, 0.2s) ease, box-shadow 0.2s ease !important; }
    ha-card:hover { background: var(--casora-popup-tile-hover, rgba(255,255,255,0.09)) !important; transform: scale(var(--casora-popup-tile-hover-scale, 1.01)) !important; }
    ha-ripple { display: none !important; }
  `;

const cards = [];

const UI = window._casoraUI;
let _first = null;
if (UI) {
const ICON_FOR = {
moisture: 'mdi:water',
humidity: 'humidity',
illuminance: 'mdi:white-balance-sunny',
temperature: 'temp-medium',
conductivity: 'mdi:beaker-outline',
battery: 'battery',
};

const rowFor = (eid) => {
const type = getSensorType(eid);
const val = safeNum(eid);
const unit = states[eid]?.attributes?.unit_of_measurement || '';
const minOpt = type ? getThreshold(type, 'min') : null;
const maxOpt = type ? getThreshold(type, 'max') : null;
const isOk = !flagged(type);
const noVerdict = val == null || (blind && type && type !== 'battery');

const n = (v) => v == null ? ''
: v >= 1000 ? (v / 1000).toFixed(v >= 10000 ? 0 : 1) + 'k'
: String(Math.round(v));
const u = !unit ? ''
: (unit === '%' || unit.charAt(0) === '\u00b0') ? unit
: ' ' + unit;

const band = (minOpt != null && maxOpt != null)
? 'Ziel ' + n(minOpt) + '\u2013' + n(maxOpt) + u
: minOpt != null ? 'Über ' + n(minOpt) + u
: maxOpt != null ? 'Unter ' + n(maxOpt) + u
: null;

const tone = noVerdict ? null : (isOk ? null : 'warn');
return {
entity: eid,
icon: ICON_FOR[type] || 'plant',
label: type === 'battery' ? 'Akku' : cleanName(eid),
sub: tone ? (band || (!(UI.soft && UI.soft()) ? null : ({ low: 'Zu niedrig', high: 'Zu hoch' })[badTypes[type] || (type === 'illuminance' ? badTypes.dli : '')]) || null) : null,
value: val == null ? '\u2014' : n(val) + u,
valueTone: tone,
active: !!tone,
