};

const areas = [], fields = {}, fstyle = {};
const add = (name, html) => {
areas.push('"' + name + '"');
fields[name] = html;
fstyle[name] = [{ 'justify-self': 'stretch' }];
};

const _moist = sensors.find(e => getSensorType(e) === 'moisture') || null;
const _capId = 'plantcap-' + String(plant || 'x').replace(/[^a-zA-Z0-9]/g, '_');
add('head', UI.headline ? UI.headline({
title: (window.casoraPopupTitle ? window.casoraPopupTitle(this, variables, String(plantAttrs.friendly_name || '').trim() || 'Pflanze', ['Pflanze', 'Plant']) : (variables.room_name || plantAttrs.friendly_name || '').trim()) || 'Pflanze',
state: advice,
barTitle: true,
measure: 'sheet',
captionSlot: !!_moist,
captionId: _capId,
line: true,
meta: (() => { const _e = hass?.entities?.[plant]; const _a = _e?.area_id || hass?.devices?.[_e?.device_id]?.area_id;
return variables.plant_room || (_a && hass?.areas?.[_a]?.name) || null; })(),
}) : '');

if (_moist) {
const _dry = getThreshold('moisture', 'min');
add('watercap', `[[[
        const el = document.querySelector('home-assistant');
        const find = (root) => {
          if (!root) return null;
          const hit = root.getElementById ? root.getElementById('${_capId}') : null;
          if (hit) return hit;
          const kids = root.querySelectorAll ? root.querySelectorAll('*') : [];
