const problem = sensors.filter((e) => {
const t = getSensorType(e);
return flagged(t);
});
const rest = sensors.filter((e) => problem.indexOf(e) < 0);
const ordered = problem.concat(rest);
const _pk = String(plant || 'x').replace(/[^a-zA-Z0-9]/g, '_');
const _TYPE = { moisture: ['Bodenfeuchte', '7d', '#64D2FF'], temperature: ['Temperatur', '48h', '#FF9F0A'],
humidity: ['Luftfeuchtigkeit', '48h', '#0A84FF'], illuminance: ['Licht', '48h', '#FFD60A'],
conductivity: ['Nährstoffe', '7d', '#BF5AF2'], battery: ['Akku', '30d', '#30D158'] };
const _SPAN = { '48h': '48 Stunden', '7d': '7 Tage', '30d': '30 Tage' };
const _meta = (eid) => _TYPE[getSensorType(eid)] || [cleanName(eid), '48h', '#64D2FF'];
const _chartCfg = (eid) => {
const m = _meta(eid);
return { type: 'custom:casora-chart', kind: 'line', span: m[1], height: 150,
series: [{ entity: eid, name: m[0], color: m[2] }] };
};
