card.background-image:
[[[
const host = this;
const setBg = (u) => { host.style.setProperty('--casora-cam-img', u ? `url("${u}")` : 'none'); };
const isWeich = () => { try { return getComputedStyle(document.documentElement).getPropertyValue('--casora-tile-fallback-name').trim() === '1'; } catch (e) { return false; } };
const weich = isWeich();
const picNow = (on) => { if (host._hcPic !== on) { host._hcPic = on; if (host.requestUpdate) host.requestUpdate('_config', undefined); } };
const srcId = entity?.entity_id && window.casoraCamStill ? window.casoraCamStill(entity.entity_id, hass, variables) : entity?.entity_id;
host._hcSrc = srcId;
const pic = ((srcId && states[srcId]) || entity)?.attributes?.entity_picture;
const s0 = String(entity?.state || '').toLowerCase();
const dead = s0 !== 'recording' && s0 !== 'off' && (!!window._casoraCamDead?.[entity?.entity_id] || !!window.casoraCamOffline?.(entity?.entity_id, states, variables))
&& weich;
if (s0 === 'off' || !pic || entity?.state === 'unavailable' || dead) {
host._hcWant = null;
clearTimeout(host._hcRetry); host._hcRetry = null;
clearInterval(host._hcTick); host._hcTick = null;
if (host._hcBlob) { URL.revokeObjectURL(host._hcBlob); host._hcBlob = null; }
setBg(null);
host._hcPic = false;
return "none";
}
const url = pic.startsWith("/") ? `${window.location.origin}${pic}` : pic;
if (!host._hcLoad) host._hcLoad = (attempt) => {
const u = host._hcWant;
if (!u || host._hcBusy === u) return;
host._hcBusy = u;
let at = Date.now();
fetch(attempt ? `${u}${u.includes('?') ? '&' : '?'}_r=${Date.now()}` : u, { cache: 'no-store' })
.then((r) => { at = Date.now(); return r.ok ? r.blob() : Promise.reject(r.status); })
.then((b) => {
if (host._hcWant !== u || !b.size) return;
return (isWeich() && window.createImageBitmap ? createImageBitmap(b).then((bm) => {
const c = document.createElement('canvas'); c.width = 8; c.height = 8;
const x = c.getContext('2d'); x.drawImage(bm, 0, 0, 8, 8);
const px = x.getImageData(0, 0, 8, 8).data; const hi = [0, 0, 0], lo = [255, 255, 255];
for (let i = 0; i < px.length; i += 4) for (let k = 0; k < 3; k++) { hi[k] = Math.max(hi[k], px[i + k]); lo[k] = Math.min(lo[k], px[i + k]); }
return Math.max(hi[0], hi[1], hi[2]) < 14 || Math.max(hi[0] - lo[0], hi[1] - lo[1], hi[2] - lo[2]) < 6;
}).catch(() => false) : Promise.resolve(false)).then((black) => {
if (host._hcWant !== u) return;
const old = host._hcBlob;
host._hcBlob = black ? null : URL.createObjectURL(b);
setBg(host._hcBlob);
if (old) setTimeout(() => URL.revokeObjectURL(old), 1000);
const hs = (host._hass && host._hass.states) || document.querySelector('home-assistant')?.hass?.states;
const src = host._hcSrc;
const ts = src && src.indexOf('image.') === 0 ? Date.parse(hs?.[src]?.state || '') : NaN;
host._hcAt = black ? 0 : (isFinite(ts) ? Math.min(ts, at) : at);
if (host._hcPic === !black) { if (host.requestUpdate) host.requestUpdate('_config', undefined); }
else picNow(!black);
});
})
.catch(() => {
if (host._hcWant !== u) return;
if (!host._hcBlob) picNow(false);
if (attempt < 8) host._hcRetry = setTimeout(() => { host._hcRetry = null; host._hcLoad(attempt + 1); }, Math.min(2000 * 2 ** attempt, 30000));
})
.finally(() => { if (host._hcBusy === u) host._hcBusy = null; });
};
if (host._hcWant !== url) {
host._hcWant = url;
clearTimeout(host._hcRetry); host._hcRetry = null;
host._hcLoad(0);
}
const every = (window.casoraCamRefresh ? window.casoraCamRefresh(variables) : 10) * 1000;
if (host._hcTick && host._hcEvery !== every) { clearInterval(host._hcTick); host._hcTick = null; }
if (!host._hcTick) {
host._hcEvery = every;
const ref = window.WeakRef ? new WeakRef(host) : { deref: () => host };
const tick = setInterval(() => {
const h = ref.deref();
if (!h || !h._hcWant) { clearInterval(tick); if (h && h._hcTick === tick) h._hcTick = null; return; }
if (document.visibilityState !== 'visible' || !h.isConnected || !h.getClientRects().length) return;
if (h._hcPic === true && h._hcAt && window.casoraCamAge && h.requestUpdate
&& window.casoraCamAge(Date.now() - h._hcAt, every / 1000) !== h._hcLbl) h.requestUpdate('_config', undefined);
if (h._hcRetry) return;
const hs = (h._hass && h._hass.states) || document.querySelector('home-assistant')?.hass?.states;
const p = h._hcSrc && hs?.[h._hcSrc]?.attributes?.entity_picture;
const nu = p ? (p.startsWith('/') ? `${window.location.origin}${p}` : p) : null;
if (nu && nu !== h._hcWant) { h._hcWant = nu; h._hcLoad(0); return; }
h._hcLoad(1);
}, every);
host._hcTick = tick;
}
if (weich && host._hcPic !== true) return "none";
return "linear-gradient(rgba(20,20,20,0.4), rgba(20,20,20,0.6)), var(--casora-cam-img, none)";
]]]

