casora_cover.state_display:
[[[
const fit = (t) => window.casoraStateFit?.(t) ?? t;
const coverList = Array.isArray(variables?.covers) ? variables.covers : [];
const isGroupSummary = coverList.length > 1 && !coverList.includes(entity?.entity_id);
if (isGroupSummary) {
let openCount = 0;
let closedCount = 0;
for (const id of coverList) {
const cst = hass.states[id];
if (!cst) continue;
const cpos = Number(cst.attributes?.current_position);
const isOpen = Number.isFinite(cpos)
? cpos > 0
: ['open', 'opening'].includes((cst.state || '').toLowerCase());
if (isOpen) openCount++; else closedCount++;
}
if (openCount > 0 && closedCount > 0) {
return fit(`${openCount} von ${openCount + closedCount} offen`);
}
}
const st = (entity?.state || '').toLowerCase();
const pos = Number(entity?.attributes?.current_position);
if (['open', 'closed'].includes(st) && Number.isFinite(pos) && pos > 0 && pos < 100) {
return fit(pos >= 50 ? `${pos}% Geöffnet` : `${100 - pos}% Geschlossen`);
}
if (!entity?.state) return "";
if (window._casoraStateText) return fit(window._casoraStateText(hass, entity));
return fit((() => { try { return hass.formatEntityState(entity); } catch (e) { return ''; } })() || entity?.state);
]]]

