icon_tap_action.action:
[[[
const s = String(entity?.state || '').toLowerCase();
if (s === 'unavailable' || s === 'unknown') return 'none';
const feats = Number(entity?.attributes?.supported_features || 0);
return (s === 'off' ? (feats & 128) : (feats & 256)) ? 'call-service' : 'none';
]]]

casora_media.state_display:
[[[
const sRaw = String(entity?.state || "");
const s    = sRaw.toLowerCase();
const a    = entity?.attributes || {};
const cap  = (x) => (x ? x.charAt(0).toUpperCase() + x.slice(1) : "");
const esc  = (t) => String(t ?? "")
.replaceAll("&","&amp;")
.replaceAll("<","&lt;")
.replaceAll(">","&gt;")
.replaceAll('"',"&quot;")
.trim();
if (s === "playing") {
const id       = entity?.entity_id || "";
const friendly = (a.friendly_name || "").toLowerCase();
const type   = String(a.media_content_type || "").toLowerCase();
const title  = (a.media_title || a.title || "").trim();
const artist =
(a.media_artist || a.artist || a.media_album_artist || "").trim();
const app    = (a.app_name || "").trim();
const source = (a.source || a.media_channel || "").trim();
const isMusic =
type === "music" ||
id.includes("spotify") ||
(!!artist && !["movie","video","tvshow"].includes(type));
let label = "";
if (isMusic) {
if (artist && title) label = `${artist} - ${title}`;
else label = title || artist || app || source || 'Wiedergabe';
} else {
label = title || app || source || 'Wiedergabe';
}
const isSonos = id.includes("sonos") || friendly.includes("sonos");
const bareInputs = ["tv","hdmi","arc","hdmi arc","optical","line-in","line in"];
let looksLikeBareInput = false;
if (isSonos) {
const tLow = title.toLowerCase();
const sLow = source.toLowerCase();
if (
title && (
bareInputs.includes(tLow) ||
(source && tLow === sLow)
)
) {
looksLikeBareInput = true;
}
}
const hasRichMeta =
!!(a.media_artist || a.media_album_artist || a.media_series_title || a.media_episode_title);
const mediaTypes = ["music","movie","video","tvshow","game"];
const fromRichApp =
/youtube|netflix|hulu|disney|max|prime|spotify|apple tv|apple music|paramount|peacock/i
.test(app);
const isRichPlayback = !looksLikeBareInput && (
hasRichMeta ||
mediaTypes.includes(type) ||
fromRichApp
);
if (!isRichPlayback) return esc(label) || 'Wiedergabe';
return `<span class="casora-media-state">${esc(label)}</span>`;
}
const M = { on: 'An', off: 'Aus', idle: 'Inaktiv', paused: 'Pausiert', playing: 'Wiedergabe', buffering: 'Lädt', standby: 'Standby', unavailable: 'Nicht verfügbar', unknown: 'Unbekannt' };
if (M[s]) return M[s];
if (!s) return "Aus";
return window._casoraStateText ? window._casoraStateText(hass, entity) : cap(s);
]]]

card.--casora-icon-mask-image:
[[[
const icon = variables.icon;
if (icon === 'ps5') return `url('${window.casoraIconUrl(variables.is_active ? 'ps5' : 'ps5_off')}')`;
return `url('${window.casoraIconUrl(icon || 'speaker')}')`;
]]]

card.--casora-media-icon-bg:
[[[
if (variables.has_artwork) return 'rgba(255,255,255,0.10)';
if (!variables.is_active) return 'var(--casora-icon-circle-bg, rgba(0,0,0,0.20))';
if (variables.icon === 'ps5') return 'rgba(10,10,10,0.85)';
return 'var(--casora-icon-color-current)';
]]]

casora_popup.content:
[[[
const UI = window._casoraUI;
if (!UI || !entity) return { type: 'vertical-stack', cards: [] };
const id = entity?.entity_id;
const reg = hass.entities || {};
const devId = reg[id]?.device_id;
const areaId = reg[id]?.area_id || (devId ? hass.devices?.[devId]?.area_id : null);
const roomName = variables.room_name || (areaId ? hass.areas?.[areaId]?.name : null) || null;

const uiCard = {
type: 'custom:button-card',
entity: id,
triggers_update: [id].concat(variables.volume_entity ? [variables.volume_entity] : []),
variables: { room_name: roomName, icon: variables.icon || null, volume_entity: variables.volume_entity || null },
card_mod: { style:
'
:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
+ '
ha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
+ '
ha-card { will-change: auto !important; }'
