    +   'box-shadow:0 18px 40px -18px rgba(0,0,0,.85);' + (active && st !== 'playing' ? 'transform:scale(.92);' : '') + 'transition:transform .4s cubic-bezier(.36,0,.16,1);}'
    + '.hm-art::after{content:"";position:absolute;inset:0;border-radius:inherit;box-shadow:inset 0 0 0 1px rgba(255,255,255,.10);pointer-events:none;}'
    + '.hm-art img{width:100%;height:100%;object-fit:cover;display:block;}'
    + '.hm-t{font-size:22px;font-weight:600;letter-spacing:-0.02em;color:' + T.ink + ';margin-top:18px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}'
