    +   'background:var(--casora-popup-row-fill, rgba(255,255,255,0.10));border-radius:var(--casora-popup-row-radius, 20px);padding:8px 10px;box-sizing:border-box;}'
    + '.hm-vol .hm-b{width:40px;height:40px;}'
    + '.hm-vol .hm-hit{flex:1;padding:14px 0;margin:-14px 0;cursor:pointer;touch-action:none;}'
    + '.hm-vol .hm-track{height:6px;pointer-events:none;}'
