    + '.hm-pw{width:100%;margin-top:22px;}'
    + '</style>';
  /* Weich (01.10.2026): Zusatzregeln aus scripts/local/07-weich-spezial.js. */
  if (UI.soft && UI.soft() && window._casoraMediaSoft) out += window._casoraMediaSoft.css();

