          : '')
      + '<div class="hm-b" data-casora-svc="' + svc('volume_set', { volume_level: clamp(volLvl - 0.05) }) + '">'
      +   '<svg width="18" height="18" viewBox="0 0 20 20"><path d="M4 10H16" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/></svg></div>'
