return on ? 'calc(var(--thermo-rail-top, 18px) + 2 * (var(--thermo-btn-h, 44px) + var(--thermo-btn-gap, 6px)))' : 'var(--thermo-toggle-top)';
]]]

ctl_down.transition-delay:
[[[
const on = states[variables.thermostat_toggle_helper]?.state === "on" && states['input_text.casora_thermostat_active_entity']?.state === (window.casoraOverlayKey?.(entity?.entity_id) ?? entity?.entity_id);
const commit = !!(window._casoraThermoCommit && Date.now() - window._casoraThermoCommit < 1500);
const move = on ? 2 * 0.018 : (commit ? 0.000 : 0.000);
const fade = on ? move : move + 0.10;
const m = move.toFixed(3) + 's';
return `${m}, ${m}, ${m}, ${m}, ${fade.toFixed(3)}s, 0s, 0s`;
]]]

