if (n && !n.startsWith('[[[')) return n;
return (window.casoraClimateMembers ? window.casoraClimateMembers(entity, states).length : entity?.attributes?.member_entities) ? 'Fußbodenheizung' : (entity?.attributes?.friendly_name || 'Thermostat');
]]]

variables.has_controls:
[[[
if (variables.size === 'large' && /^\/[^/]*[-_]mobile(\/|$)/i.test(window.location.pathname)) return true;
return !window.matchMedia('(max-width: 767px) and (orientation: portrait), (max-height: 500px) and (orientation: portrait), (max-height: 600px) and (orientation: landscape)').matches;
]]]

variables.show_toggle:
[[[
