const _grp = Array.isArray(_mem) && _mem.length > 1;
if (_grp && window._casoraSoft && window._casoraSoft()) return false;
return variables.has_controls;
]]]

variables.toggle_service_data:
[[[
const st = entity?.state;
if (st && !['off','unavailable','unknown'].includes(st)) {
return { entity_id: entity?.entity_id, hvac_mode: 'off' };
}
const modes = (entity?.attributes?.hvac_modes || []).filter((m) => m !== 'off');
