const lvl = (id) => { const s=(states[id]?.state||'').toLowerCase(); return s.includes('warnung')||s.includes('kritisch')?true:false; };
return (fwSt&&lvl(fwSt))||(swSt&&lvl(swSt))||(ttSt&&lvl(ttSt));
]]]

casora_aquarium.state_display:
[[[
const fwId = variables.entity_freshwater;
const swId = variables.entity_saltwater;
const ttId = variables.entity_turtle;
const fwSt = fwId ? fwId.replace('_temperatur_temperature','_temperaturstatus') : null;
const swSt = swId ? swId.replace('_temperatur_temperature','_temperaturstatus') : null;
const ttSt = ttId ? ttId.replace('_temperatur_temperature','_temperaturstatus') : null;
const lvl = (id) => { const s=(states[id]?.state||'').toLowerCase(); return s.includes('kritisch')?2:s.includes('warnung')?1:0; };
const worst = Math.max(fwSt?lvl(fwSt):0, swSt?lvl(swSt):0, ttSt?lvl(ttSt):0);
if (worst >= 2) return 'Kritisch';
if (worst >= 1) return 'Warnung';
const ids = [fwId, swId, ttId].filter(Boolean);
const nums = ids.map(id => parseFloat(states[id]?.state)).filter(n => !isNaN(n));
if (nums.length === 0) return '—';
const min = (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(Math.min(...nums), 1);
const max = (window.casoraNum || ((x, a, b) => Number(x).toLocaleString(window.casoraLocale ? window.casoraLocale() : 'de-DE', { minimumFractionDigits: a, maximumFractionDigits: b == null ? a : b })))(Math.max(...nums), 1);
const fit = (t) => window.casoraStateFit?.(t) ?? t;
return fit(min === max ? min + ' °C' : min + ' – ' + max + ' °C');
]]]

