casora_badge_contact_group.extra_styles:
[[[
const v = variables?.enabled;
const enabled = (v === undefined || v === null) ? true :
(typeof v === 'boolean') ? v :
(typeof v === 'number') ? v !== 0 :
!['false','0','no','off','disabled'].includes(String(v).trim().toLowerCase());
const st = String(entity?.state ?? '').trim().toLowerCase();
const noEntity = !entity?.entity_id;
const isUnavailable = !st || ['unknown','unavailable'].includes(st);

const dom = String(entity?.entity_id || '').split('.')[0];
const dc = String(entity?.attributes?.device_class || '').toLowerCase();
const nameRaw = String(entity?.attributes?.friendly_name || '').toLowerCase();
const isWindow = dc === 'window' || nameRaw.includes('fenster') || nameRaw.includes('window');

let name = 'lock';
if (isUnavailable) name = 'default';
else if (dom === 'camera') name = 'doorbell';
else if (dom === 'lock') name = st === 'locked' ? 'lock-fill' : 'lock-open-fill';
else if (dom === 'alarm_control_panel') name = ((window._casoraSoft && window._casoraSoft()) && window.casoraSecurityIcon)
? window.casoraSecurityIcon(entity.entity_id, st, entity.attributes)
: (st === 'disarmed' || st === 'triggered') ? 'shield_alarm' : 'shield_check';
else if (dom === 'binary_sensor' || dom === 'cover') {
const isOpen = st === 'on' || st === 'open';
name = isWindow ? (isOpen ? 'window-open' : 'window-closed') : (isOpen ? 'door-open' : 'door-closed');
}
const URL = window.casoraIconUrl(name);
const SIZE = variables?.icon_size || '88%';

return `:host{display:${(!enabled || noEntity) ? 'none' : 'inline-block'} !important;${variables?.inline ? 'order:var(--casora-badge-order-security,1);' : ''}}
    #img-cell, .img-cell{ position: relative; }

    #img-cell #icon, .img-cell #icon{
      color: transparent !important;
      opacity: 0 !important;
    }

    #img-cell::before,
    .img-cell::before{
      content: '';
      position: absolute;
      inset: 0;
      background-color: color-mix(in srgb, var(--casora-badge-glyph, #fff) var(--casora-badge-circle-mix, 0%), var(--casora-badge-icon-color, var(--casora-badge-security-color, #00c3d0))) !important;
      scale: var(--casora-badge-glyph-scale, none);
      -webkit-mask: url('${URL}') no-repeat center / auto ${SIZE};
      mask: url('${URL}') no-repeat center / auto ${SIZE};
      transform: translateZ(0);
    }`;
]]]

casora_badge_contact_group.icon:
[[[
const id = String(entity?.entity_id || '');
const dom = id.split('.')[0];
const s = String(entity?.state || '').toLowerCase();
const dc = String(entity?.attributes?.device_class || '').toLowerCase();

if (dom === 'lock') return s === 'locked' ? 'mdi:lock' : 'mdi:lock-open-variant';
if (dom === 'alarm_control_panel')
return s === 'disarmed' ? 'mdi:shield-off-outline' : 'mdi:shield-check';
if (dom === 'camera') return 'mdi:cctv';
if (dc === 'garage' || dc === 'garage_door') return 'mdi:garage';
if (dc === 'window') return s === 'on' ? 'mdi:window-open' : 'mdi:window-closed';
if (dc === 'motion') return 'mdi:motion-sensor';
return s === 'on' ? 'mdi:door-open' : 'mdi:door-closed';
]]]

casora_badge_contact_group.name:
[[[
const esc = (t) => String(t ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const id  = String(entity?.entity_id || '');
const dom = id.split('.')[0];
const s   = String(entity?.state || '').toLowerCase();
const dc  = String(entity?.attributes?.device_class || '').toLowerCase();
const tilt = entity?.attributes?.tilt === true || entity?.attributes?.tilt === 'true'
|| (s === 'on' && !('tilt' in (entity?.attributes || {})) && !/kombi|combined/i.test(id + ' ' + (entity?.attributes?.friendly_name || ''))
&& /kipp|tilt/i.test(id + ' ' + (entity?.attributes?.friendly_name || '')));

const title = variables?.label || entity?.attributes?.friendly_name || 'Sicherheit';

let sub = '';
if (['unknown','unavailable',''].includes(s)) {
sub = 'Nicht verfügbar';
} else if (dom === 'lock') {
sub = s === 'locked' ? 'Verriegelt' : s === 'unlocked' ? 'Entriegelt' : s === 'jammed' ? 'Klemmt'
: s === 'open' || s === 'opening' ? 'Geöffnet' : s === 'locking' ? 'Wird verriegelt …' : s === 'unlocking' ? 'Wird entriegelt …'
: ((() => { try { return hass.formatEntityState(entity); } catch (e) { return ''; } })() || s);
} else if (dom === 'alarm_control_panel') {
sub = s === 'disarmed' ? 'Deaktiviert'
: s === 'triggered' ? 'Ausgelöst'
: s === 'armed_home' ? 'Aktiviert (Zuhause)'
: s === 'armed_away' ? 'Aktiviert (Abwesend)'
: s === 'armed_custom_bypass' ? 'Aktiviert (Bypass)'
: 'Aktiviert';
} else if (dom === 'camera') {
const alert = window.casoraCameraAlert
? window.casoraCameraAlert(hass, states, [id], variables?.alert_window_minutes) : '';
sub = s === 'recording' ? 'Aufnahme'
: s === 'streaming' ? 'Live'
: (alert || 'Sicher');
} else if (dom === 'cover') {
sub = s === 'closed' ? 'Geschlossen' : 'Geöffnet';
} else if (dc === 'motion') {
sub = s === 'on' ? 'Bewegung' : 'Frei';
} else if (tilt) {
sub = 'Gekippt';
} else {
sub = s === 'on' ? 'Geöffnet' : 'Geschlossen';
}

if ((dom === 'lock' || dom === 'alarm_control_panel') && (window._casoraSoft && window._casoraSoft()) && window.casoraSecurityWord)
sub = window.casoraSecurityWord(id, s) || sub;

return `
    <div class="badge-wrap">
      <div class="badge-title">${esc(title)}</div>
      <div class="badge-sub">${esc(sub)}</div>
    </div>
  `;
]]]

