casora_now_playing_chip.extra_styles:
/* Entrance */
:host{
  display: block;
  --casora-card-hover-shadow: none;
  --casora-card-hover-filter: none;
  width: var(--np-tile-width, 100%);
  align-self: var(--np-tile-align, stretch);
  pointer-events: var(--np-chip-ptr, none);
  max-height: calc(var(--np-chip, 0) * calc(var(--casora-u-np, 10px) * 6));
  margin-top: calc(var(--np-chip, 0) * calc(var(--casora-u-np, 10px) * 1.6));
  overflow: visible;
  transition:
    max-height var(--np-chip-geo, .34s) var(--casora-ease-slide, cubic-bezier(0.4, 0, 0.2, 1)),
    margin-top var(--np-chip-geo, .34s) var(--casora-ease-slide, cubic-bezier(0.4, 0, 0.2, 1));
}

/* Rim */
:host::after{
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: var(--np-chip-radius, 16px);
  z-index: 6;
  box-shadow:
    0.5px 0 1px -0.5px rgba(0,0,0,0.25),
    -0.5px 0 1px -0.5px rgba(0,0,0,0.25),
    0 0.5px 0.5px -0.5px rgba(0,0,0,0.10),
    0 1px 3px rgba(0,0,0,0.12);
  opacity: calc(var(--np-chip, 0) * (1 - var(--np-min, 0)));
}

ha-card{
  /* height = art (40px) + 8px top/bottom inset */
  height: calc(var(--np-chip, 0) * calc(var(--casora-u-np, 10px) * 5.6)) !important;
  min-height: calc(var(--np-chip, 0) * calc(var(--casora-u-np, 10px) * 5.6)) !important;
  cursor: pointer;
  transform-origin: 30% -40%;
  /* translate, not transform — transform is already driven by rail-shift/demotion FLIPs on this element via WAAPI; no scale since transform-origin belongs to those FLIPs. */
  translate:
    calc(var(--np-min, 0) * 30px)
    calc(var(--np-min, 0) * -20px);
  opacity: calc(1 - var(--np-min, 0));
  /* Resting state only; --np-min drives the actual spring via WAAPI, so these aren't in the transition list. */
  transition-property: backdrop-filter, -webkit-backdrop-filter !important;
  transition-duration: .15s !important;
  transition-timing-function: ease !important;
}

ha-ripple, mwc-ripple { display: none !important; }

/* Artwork wash */
ha-card::after{
  content: '';
  position: absolute;
  inset: -60px;
  pointer-events: none;
  z-index: 0;
  /* No flat black layer over the art (the large tile's bloom has none either) — dimming the
     cover before compositing, then landing it at 0.30, is what left the pill gray while the
     large tile read purple off the same artwork. */
  background:
    var(--bg-url, none),
    linear-gradient(var(--casora-badge-art-floor, rgba(160,160,160,0.28)) 0 0);
  background-blend-mode: lighten;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  filter: blur(24px) saturate(1.6);
  /* ── CHIP BLOOM — tune this fallback ── Only the fallback moves, so mobile's ancestor-set 0.62 still wins. */
  opacity: calc(var(--np-chip, 0) * var(--np-chip-has-art, 0) * var(--np-bloom-strength, var(--casora-np-bloom, 0.48)));
}

/* Specular ring */
:host::before{
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: var(--np-chip-radius, 16px);
  z-index: 4;
  padding: var(--np-chip-ring-thickness, 0.9px);
  backdrop-filter: brightness(var(--np-chip-ring-boost, 1.2)) saturate(var(--casora-badge-ring-sat, 1.8));
  -webkit-backdrop-filter: brightness(var(--np-chip-ring-boost, 1.2)) saturate(var(--casora-badge-ring-sat, 1.8));
  mix-blend-mode: screen;
  -webkit-mask:
    linear-gradient(to bottom,
      rgba(0,0,0,.16) 0%,
      rgba(0,0,0,0.06) 25%,
      rgba(0,0,0,0) 40%,
      rgba(0,0,0,0) 60%,
      rgba(0,0,0,0.06) 75%,
      rgba(0,0,0,0.05) 100%),
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: source-in, xor;
          mask-composite: intersect, exclude;
  opacity: calc(var(--np-chip, 0) * (1 - var(--np-min, 0)) * var(--casora-np-ring, 1));
  transform: translateZ(0);
  backface-visibility: hidden;
}

#container{
  position: relative !important;
  z-index: 2 !important;
}

/* Hairline */
#container::before{
  content: '';
  position: absolute;
  inset: 0px -8px 0px -8px;
  border-radius: var(--np-chip-radius, 16px);
  pointer-events: none;
  box-shadow: var(--casora-np-chip-rim,
    inset 0 0.5px 0 rgba(255,255,255,0.18),
    inset 0 0 0 0.5px rgba(255,255,255,0.08),
    inset 0 -0.5px 0 rgba(255,255,255,0.08));
}

/* Hover tint */
#container::after{
  content: '';
  position: absolute;
  inset: 0px -8px 0px -8px;
  border-radius: var(--np-chip-radius, 16px);
  pointer-events: none;
  z-index: 5;
  background: var(--casora-np-hover, rgba(255,255,255,0.05));
  opacity: 0;
  transition: opacity .40s ease;
}

@media (hover: hover) {
  ha-card:hover #container::after{
    opacity: 0.6;
    transition: opacity .18s ease;
  }
}

:host ha-card,
:host ha-card:hover,
:host ha-card:focus,
:host ha-card:active{
  box-shadow: none !important;
}

@media (prefers-reduced-motion: reduce) {
  :host{
    transform: none;
    transition: opacity .12s linear, max-width .12s linear;
  }
}

.np-chip-art{
  width: calc(var(--np-chip, 0) * calc(var(--casora-u-np, 10px) * 4));
  height: calc(var(--np-chip, 0) * calc(var(--casora-u-np, 10px) * 4));
  border-radius: var(--np-chip-art-radius, 16px);
  background-image: var(--np-chip-art, none);
  background-size: cover;
  background-position: center;
  background-color: var(--casora-np-art-fill, rgba(255,255,255,0.10));
  box-shadow: var(--casora-np-art-rim, inset 0 0 0 0.5px rgba(255,255,255,0.14));
  flex: none;
  position: relative;
}


.np-chip-wrap{
  display: flex;
  flex-direction: column;
  gap: 0px;
  min-width: 0;
}

.np-chip-top{
  font-size: calc(var(--casora-u-np, 10px) * 1.3);
  font-weight: 700;
  line-height: 1.2;
  color: var(--primary-text-color, #fff);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.np-chip-bot{
  font-size: calc(var(--casora-u-np, 10px) * 1.2);
  font-weight: 500;
  line-height: 1.2;
  /* Same translucent white as the large tile's .np-sub — the artwork hue reaches this row
     through the bloom behind it, not by tinting the glyph color directly. */
  color: var(--casora-np-sub, rgba(255,255,255,0.62));
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

casora_now_playing_chip.name:
