casora_popup.content:
[[[
const UI = window._casoraUI;
if (!UI) return { type: 'vertical-stack', cards: [] };

const _cc = window.casoraContacts ? window.casoraContacts(hass) : { groups: [], sub: {}, excl: [] };
const GROUPS = _cc.groups;
const _SUB = _cc.sub;
const _EXCL = _cc.excl;
const _TILT = _cc.tilt || {};
const _tilted = (id) => states[id]?.attributes?.tilt === true || (!!_TILT[id] && (states[_TILT[id]]?.state || '') === 'on');
const _mem = (arr) => arr.filter((x) => !_EXCL.includes(x)).map((x) => _SUB[x] || x).filter((x, i, a) => a.indexOf(x) === i);

const isOpen = (id) => {
const s = (states[id]?.state || '').toLowerCase();
return s === 'on' || s === 'open' || s === 'opening' || (!!_TILT[id] && (states[_TILT[id]]?.state || '') === 'on');
};

const allMembers = [];
GROUPS.forEach((g) => {
const mems = _mem(g.members || []);
mems.forEach((id) => allMembers.push(id));
});

const openIds = allMembers.filter(isOpen);
const oc = openIds.length, tot = allMembers.length;

const tc = openIds.filter((id) => _tilted(id)).length;
const value = oc === 0
? 'Alle geschlossen'
: tc === oc
? tc + ' gekippt'
: oc === tot
? 'Alle geöffnet'
: oc + ' geöffnet';

const ago = (iso) => {
if (!iso) return null;
const ms = Date.now() - new Date(iso).getTime();
if (isNaN(ms) || ms < 0) return null;
const m = ms/60000, h = m/60, d = h/24;
if (m < 1) return 'gerade eben';
if (m < 60) return 'vor ' + Math.floor(m) + (Math.floor(m)===1?' Minute':' Minuten');
if (h < 24) return 'vor ' + Math.floor(h) + (Math.floor(h)===1?' Stunde':' Stunden');
if (d < 7)  return 'vor ' + Math.floor(d) + (Math.floor(d)===1?' Tag':' Tagen');
return 'vor ' + Math.floor(d/7) + 'w';
};
const _since = (id) => window._casoraOpenSince ? window._casoraOpenSince(states[id], states) : states[id]?.last_changed;
const newest = (oc ? openIds : allMembers).map(_since).filter(Boolean).sort((a, b) => Date.parse(a) - Date.parse(b)).pop();

const areas = [], fields = {}, fstyle = {};
const add = (name, html) => {
areas.push('"' + name + '"');
fields[name] = html;
fstyle[name] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
};

add('hero', UI.hero({
value: value,
sub: ago(newest),
center: true,
line: true,
subTone: oc > 0 ? 'warn' : null,
}));

const areaOf = (id) => {
const ent = hass?.entities?.[id];
if (!ent) return null;
const areaId = ent.area_id || (ent.device_id ? hass?.devices?.[ent.device_id]?.area_id : null);
return areaId ? (hass?.areas?.[areaId]?.name || null) : null;
};

const rowFor = (id) => {
const dc = String(states[id]?.attributes?.device_class || '').toLowerCase();
const isWindow = dc === 'window';
const open = isOpen(id);
const rawName = states[id]?.attributes?.friendly_name || id;
const area = areaOf(id);
let label = area || rawName;
let sub = null;
if (UI.soft && UI.soft()) {
const dev = hass?.devices?.[hass?.entities?.[id]?.device_id];
const dn = String((dev && (dev.name_by_user || dev.name)) || rawName).trim()
.replace(/^(kontaktsensor|kontakt|fenstersensor|t\u00fcrsensor|contact sensor|door sensor|window sensor)\s+/i, '')
.replace(/\s+(contact|kontakt)$/i, '').trim();
label = dn && dn !== area ? dn : rawName;
sub = area && label !== area ? area : null;
}
return {
entity: id,
sub: sub,
icon: isWindow ? (open ? 'window-open' : 'window-closed') : (open ? 'door-open' : 'door-closed'),
iconTone: ((window._casoraSoft && window._casoraSoft()) && window.casoraSecurityLevel) ? window.casoraSecurityColor(window.casoraSecurityLevel(hass, [id])) : open ? 'warn' : null,
label: label,
value: open ? (_tilted(id) ? 'Gekippt' : 'Geöffnet') : 'Geschlossen',
valueTone: open ? (((window._casoraSoft && window._casoraSoft()) && window.casoraSecurityLevel && window.casoraSecurityLevel(hass, [id]) === 'alarm') ? 'bad' : 'warn') : null,
active: open,
};
};

GROUPS.forEach((g, i) => {
const mems = _mem(g.members || []);
if (mems.length) add('grp' + i, UI.group(mems.map(rowFor), g.label));
});

const uiCard = {
type: 'custom:button-card',
card_mod: { style:
'\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
+ '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
+ '\nha-card { will-change: auto !important; }'
+ '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }'
},
tap_action: { action: 'none' },
show_icon: false, show_name: false, show_label: false, show_state: false,
styles: {
card: [
{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
{ padding: 'var(--casora-soft-card-top, 6px) 26px 22px 26px' },
],
grid: [
{ 'grid-template-areas': areas.join(' ') },
{ 'grid-template-columns': '1fr' },
{ 'row-gap': 'var(--casora-popup-sec-gap, 18px)' },
],
custom_fields: fstyle,
},
custom_fields: fields,
};
return { type: 'vertical-stack', cards: [window._casoraStd ? window._casoraStd(uiCard, {}) : uiCard] };
]]]

popup_styles.styles:
/* Eine Popup-Familie (01.10.2026): dieselbe Sheet-Fläche wie die Bedien-Popups –
   Fläche, Blur, Schatten und Abdunklung aus dem Standard, Höhe folgt dem Inhalt,
   Schließen-Kreuz mit demselben Abstand zur Sheet-Kante. */
.header { padding-top: var(--casora-popup-header-gap, 10px); }
--casora-popup-header-gap: 14px;
/* Aquarien: breit wie Energie, zwei Spalten ab 761 px; schmale Screens deckelt .surface selbst. */
--popup-min-width: 900px;
--popup-max-width: 920px;
--casora-popup-gutter-wide: 34px;
--casora-popup-gutter-phone: 22px;

/* No chart here, so nothing to wait for: the widgets arrive as
   soon as they are built. Read by each widget for itself, never by
   a wrapper - an animated opacity on an ancestor flattens the frost
   inside it. */
--casora-popup-plate-enter:
  casora-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --casora-popup-plate-enter: none;
}

--casora-popup-hero-label-size: 15px;
--casora-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--casora-card-hover-filter: none;
--casora-hover-filter: none;
--casora-card-hover-shadow: none;

--casora-popup-row-pad-x: 26px;
--casora-popup-row-pad-y: 15px;
--casora-popup-plate-backdrop: blur(24px) saturate(180%);
--casora-popup-chart-fill: var(--casora-sheet-chart-fill, rgba(10, 12, 16, 0.68));
--casora-popup-row-fill: var(--casora-sheet-row-fill, rgba(12, 14, 19, 0.62));
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--casora-popup-plate-shadow: var(--casora-sheet-plate-shadow,
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28));

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--casora-popup-chrome-enter:
  casora-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--casora-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--casora-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--casora-popup-plate-backdrop, none);
  box-shadow: var(--casora-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

/* Titel: mittig, solange er zwischen die Knöpfe passt; sonst ab rechts vom Schließen-Knopf (safe center), notfalls mit … am rechten Rand. Nie unter dem Schließen-Knopf. */
.header-content { left: calc(var(--casora-popup-gutter, 26px) + 56px) !important; right: calc(var(--casora-popup-gutter, 26px) + 56px) !important; margin-inline: 0 !important; width: auto !important; max-width: none !important; overflow: visible !important; align-items: safe center !important; }
.header-title { max-width: calc(100% + 56px) !important; overflow: hidden !important; text-overflow: ellipsis !important; white-space: nowrap !important; }

/* Popup-Standard (24.09.2026): Info-Popup - Abschnittsüberschriften in der Karte. */
--casora-lbl-in: block;
--casora-lbl-out: none;

