return '<div style="display:flex;gap:12px;align-items:flex-start;padding:12px 16px 14px 12px;border-radius:var(--casora-popup-row-radius, 24px);background:var(--casora-soft-row-fill, rgba(140,115,90,0.07));">'
+ '<div style="width:var(--casora-soft-icon-size, 38px);height:var(--casora-soft-icon-size, 38px);border-radius:var(--casora-soft-icon-radius, 50%);flex:none;display:flex;align-items:center;justify-content:center;background:' + info.color + ';">'
+ '<ha-icon icon="' + warningIcon(w, w.level) + '" style="--mdc-icon-size:18px;display:flex;color:' + ((window._casoraInkOn && window._casoraInkOn(info.color)) || 'var(--casora-soft-glyph, #fff)') + ';"></ha-icon></div>'
+ '<div style="min-width:0;flex:1;padding-top:1px;">'
+ '<div style="font-size:14.5px;font-weight:700;letter-spacing:-0.01em;line-height:1.3;color:' + T2.ink + ';">' + esc(title) + '</div>'
+ '<div style="font-size:12.5px;font-weight:500;color:var(--casora-soft-sub, ' + T2.ink2 + ');margin-top:1px;">' + esc(subtitle) + '</div>'
+ '<div style="font-size:13.5px;color:' + T2.ink2 + ';line-height:1.45;margin-top:8px;">' + escBr(w.description || 'Keine Detailbeschreibung verfügbar.') + '</div>'
+ (w.instruction ? '<div style="font-size:12.5px;color:var(--casora-soft-sub, ' + T2.ink3 + ');line-height:1.4;margin-top:6px;">' + escBr(w.instruction) + '</div>' : '')
