casora_popup.content:
[[[
const UI = window._casoraUI;
if (!UI || !entity) return { type: 'vertical-stack', cards: [] };
const id = entity?.entity_id;
const _id = JSON.stringify(id);
const CTRL_H = (UI.tokens && UI.tokens.controlH) || 260;
const CTRL_W = (UI.tokens && UI.tokens.controlW) || 124;
const iconOn = variables.icon && variables.icon !== 'power_on' ? variables.icon : 'power_on';
const iconOff = variables.icon && variables.icon !== 'power_on' ? variables.icon : 'power_off';

const reg = hass.entities || {};
const devId = reg[id]?.device_id;
const sib = {};
if (devId) {
Object.values(reg).forEach((e) => {
if (e.device_id !== devId || !e.entity_id.startsWith('sensor.') || !states[e.entity_id]) return;
const eid = e.entity_id;
const unit = states[eid].attributes?.unit_of_measurement;
if (unit === 'W' && !sib.power) sib.power = eid;
else if (/energy_today$/.test(eid)) sib.today = eid;
else if (unit === 'kWh' && /energy$/.test(eid) && !sib.total) sib.total = eid;
});
}
const _sib = JSON.stringify(sib);

const areas = [], fields = {}, fstyle = {};
const add = (name, html) => {
areas.push('"' + name + '"');
fields[name] = html;
fstyle[name] = [{ 'justify-self': 'stretch' }];
};

add('hero', `[[[
    const id = ${_id};
    const st = states[id]?.state;
    const ago = (iso) => {
      if (!iso) return null;
      const ms = Date.now() - new Date(iso).getTime();
      if (isNaN(ms) || ms < 0) return null;
      const m = ms/60000, h = m/60, d = h/24;
      if (m < 1) return 'gerade eben';
      if (m < 60) return 'vor ' + Math.floor(m) + (Math.floor(m)===1?' Minute':' Minuten');
      if (h < 24) return 'vor ' + Math.floor(h) + (Math.floor(h)===1?' Stunde':' Stunden');
      if (d < 7)  return 'vor ' + Math.floor(d) + (Math.floor(d)===1?' Tag':' Tagen');
      return 'vor ' + Math.floor(d/7) + 'w';
    };
    const value = st === 'on' ? 'An' : st === 'off' ? 'Aus' : st === 'unavailable' ? 'Nicht verfügbar' : 'Unbekannt';
    return window._casoraUI.hero({ value: value, sub: ago(states[id]?.last_changed), center: true });
  ]]]`);

const toggleCard = {
type: 'custom:button-card',
entity: id,
show_icon: false, show_name: false, show_state: false, show_label: false,
haptic: 'medium',
tap_action: `[[[
      const id = ${_id};
      if (!['on', 'off'].includes(states[id]?.state)) return { action: 'none' };
      return { action: 'call-service', service: 'switch.toggle', service_data: { entity_id: id } };
    ]]]`,
extra_styles: `
      :host { display: block !important;
              --casora-card-hover-filter: none;
              --casora-hover-filter: none;
              --casora-card-hover-shadow: none;
              --button-card-box-shadow-hover: none; }
      ha-card { background: transparent !important; border: none !important;
                box-shadow: none !important; backdrop-filter: none !important;
                padding: 0 !important; cursor: pointer !important; }
      #container { padding: 0 !important; }
      ha-ripple { display: none !important; }
    `,
styles: {
card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
grid: [{ 'grid-template-areas': '"t"' }, { 'grid-template-columns': 'auto' },
{ 'justify-items': 'center' }],
custom_fields: { t: [{ 'line-height': '0' }] },
},
custom_fields: {
t: `[[[
        const id = ${_id};
        const s = states[id]?.state;
        const atTop = s === 'on';
        const dead = s !== 'on' && s !== 'off';

        const W = ${CTRL_W}, H = ${CTRL_H}, PAD = 7;
        const TH = Math.round(H * 0.49);
