          +   'top:0;height:' + TH + 'px;border-radius:' + Math.round((W - PAD * 2) * 0.30) + 'px;'
          +   'background:' + thumbFill + ';transform:translateY(' + to + 'px);'
          +   'display:flex;align-items:center;justify-content:center;}'
