          + (moved
              ? '.swtg-t{animation:swtg-mv .34s cubic-bezier(.36,0,.16,1) forwards,swtg-cf .34s ease forwards}'
              + '@keyframes swtg-mv{from{transform:translateY(' + from + 'px)}to{transform:translateY(' + to + 'px)}}'
              + '@keyframes swtg-cf{from{background:' + pThumb + '}to{background:' + thumbFill + '}}'
              + '.swtg-i{animation:swtg-kf .34s ease forwards}'
              + '@keyframes swtg-kf{from{background-color:' + pInk + '}to{background-color:' + inkFill + '}}'
              : '')
          + '</style>'
          + '<div class="swtg"><div class="swtg-t"><div class="swtg-i"></div></div></div>';
      ]]]`,
},
};
add('toggle', { card: toggleCard });

add('rows', `[[[
    const id = ${_id};
