casora_trash.state_display:
[[[
if (!window._casoraTrashFetch) {
window._casoraTrashFetch = (h, cal) => {
const c = window._casoraTrashCal;
if (!h || !h.callApi || window._casoraTrashBusy) return;
if (c && c.id === cal && Date.now() - c.ts < 6 * 3600000) return;
window._casoraTrashBusy = true;
const s = new Date(); s.setHours(0, 0, 0, 0);
const e = new Date(s.getTime() + 400 * 86400000);
h.callApi('GET', 'calendars/' + cal + '?start=' + encodeURIComponent(s.toISOString()) + '&end=' + encodeURIComponent(e.toISOString()))
.then((r) => { window._casoraTrashCal = { id: cal, ts: Date.now(), ev: Array.isArray(r) ? r : [] }; })
.catch(() => {})
.finally(() => { window._casoraTrashBusy = false; });
};
}
const W = window.casoraDevice && window.casoraDevice.waste ? window.casoraDevice.waste(hass, variables) : null;
const fit = (t) => window.casoraStateFit?.(t) ?? t;
if (!W) return '…';
if (W.calendar) window._casoraTrashFetch(hass, W.calendar);
const label = W.next ? W.next.label : '';
const days = W.days;
if (days == null && window.casoraDevice.wasteDown && window.casoraDevice.wasteDown(hass, W)) return fit('Nicht erreichbar');
if (days == null) return fit(W.bins.length ? 'Keine Daten' : 'Keine Tonnen gefunden');
if (days === 0) return fit(`Heute ${label}`);
if (days === 1) return fit(`Morgen ${label}`);
return fit(`${days} Tage · ${label}`);
]]]

casora_popup.content:
[[[
const UI = window._casoraUI;
if (!UI) return { type: 'vertical-stack', cards: [] };
const T = UI.tokens;
const esc = UI.esc;

const W = window.casoraDevice && window.casoraDevice.waste ? window.casoraDevice.waste(hass, variables) : null;
if (!W) return { type: 'vertical-stack', cards: [] };
const CAL = W.calendar;
const REMINDER = W.reminder;
const DUTY = W.months || [];
if (CAL && window._casoraTrashFetch) window._casoraTrashFetch(hass, CAL);

const BINS = W.bins;
const DAY = 86400000;
const WD = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
const MON = ['Jan', 'Feb', 'Mär', 'Apr', 'Mai', 'Jun', 'Jul', 'Aug', 'Sep', 'Okt', 'Nov', 'Dez'];
const MONL = ['Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'];
const today = new Date(); today.setHours(0, 0, 0, 0);
const ISO = /^\d{4}-\d{2}-\d{2}$/;
const dOf = (iso) => { const d = new Date(String(iso).slice(0, 10) + 'T00:00:00'); return isNaN(d) ? null : d; };
const key = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
const diff = (d) => Math.round((d - today) / DAY);
const fmt = (d) => d.toLocaleDateString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { weekday: 'short', day: '2-digit', month: '2-digit' });
const fmtS = (d) => d.toLocaleDateString((window.casoraLocale ? window.casoraLocale() : 'de-DE'), { day: '2-digit', month: '2-digit' });
const rel = (n) => n === 0 ? 'Heute' : n === 1 ? 'Morgen' : 'in ' + n + ' Tagen';

const cal = (window._casoraTrashCal && window._casoraTrashCal.id === CAL) ? window._casoraTrashCal.ev : [];
const datesOf = (b) => {
const a = states[b.id]?.attributes || {};
const set = {};
Object.keys(a).forEach((k) => {
if (ISO.test(k)) set[k] = 1;
else if (typeof a[k] === 'string' && ISO.test(a[k])) set[a[k]] = 1;
});
cal.forEach((e) => {
const s = e && e.start && (e.start.date || e.start.dateTime);
if (s && b.re.test(e.summary || '')) set[String(s).slice(0, 10)] = 1;
});
return Object.keys(set).map(dOf).filter((d) => d && d >= today).sort((x, y) => x - y);
};

const bins = BINS.map((b) => {
const st = states[b.id];
if (!st) return null;
const ds = datesOf(b);
let days = parseInt(st.state, 10);
if (isNaN(days)) days = parseInt(st.attributes?.daysTo, 10);
if (isNaN(days) && ds.length) days = diff(ds[0]);
if (isNaN(days)) return null;
let next = ds.find((d) => diff(d) === days);
if (!next && ds.length) { next = ds[0]; days = diff(next); }
if (!next) next = new Date(today.getTime() + days * DAY);
const gaps = ds.slice(1).map((d, i) => Math.round((d - ds[i]) / DAY)).sort((x, y) => x - y);
const weeks = gaps.length ? Math.round(gaps[Math.floor(gaps.length / 2)] / 7) : 0;
const cnt = [0, 0, 0, 0, 0, 0, 0];
ds.forEach((d) => cnt[d.getDay()]++);
const usual = ds.length >= 3 ? cnt.indexOf(Math.max.apply(null, cnt)) : null;
return Object.assign({}, b, { days, next, ds, weeks, usual });
}).filter(Boolean).sort((x, y) => x.days - y.days);

const byDay = {};
bins.forEach((b) => b.ds.forEach((d) => { (byDay[key(d)] = byDay[key(d)] || []).push(b); }));

const plate = (inner, pad) => '<div class="hui-plate" style="background:var(--casora-popup-row-fill, rgba(255,255,255,0.10));'
+ 'border-radius:var(--casora-popup-row-radius, 20px);overflow:hidden;'
+ 'box-shadow:var(--casora-popup-plate-shadow, none);'
+ 'backdrop-filter:var(--casora-popup-plate-backdrop, none);'
+ '-webkit-backdrop-filter:var(--casora-popup-plate-backdrop, none);'
+ 'padding:' + (pad || 'var(--casora-popup-row-pad-y, 8px) var(--casora-popup-row-pad-x, 16px)') + ';'
+ 'font-family:' + T.font + ';text-align:left;">' + inner + '</div>';
const title = (t, v, vTone) => '<div style="display:flex;justify-content:space-between;align-items:baseline;gap:12px;'
+ 'padding:0 4px 8px;">'
+ '<div style="font-size:var(--casora-h15-fs,15px);font-weight:var(--casora-h15-fw,600);letter-spacing:var(--casora-h15-ls,-0.01em);text-transform:var(--casora-h15-tt,none);color:var(--casora-h15-c, ' + T.ink + ');">' + esc(t) + '</div>'
+ (v ? '<div style="font-size:15px;letter-spacing:-0.01em;color:' + (vTone || T.ink2) + ';white-space:nowrap;">' + esc(v) + '</div>' : '')
+ '</div>';
const gap = '<div style="height:18px"></div>';

const first = bins[0];
const DOWN = window.casoraDevice.wasteDown ? window.casoraDevice.wasteDown(hass, W) : null;
const duty = W.duty === true;
let out = '<style>ha-card.disabled{pointer-events:auto!important;}'
+ '.tr-cal{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));row-gap:4px;}'
+ '.tr-wd{font-size:12px;font-weight:600;color:' + T.ink3 + ';text-align:center;padding-bottom:6px;}'
+ '.tr-d{display:flex;flex-direction:column;align-items:center;gap:4px;padding:4px 0 6px;border-radius:12px;}'
+ '.tr-d.hit{background:' + T.fill + ';}'
+ '.tr-n{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;font-size:16px;letter-spacing:-0.02em;color:' + T.ink + ';}'
+ '.tr-d.past .tr-n,.tr-d.past .tr-dots{opacity:.32;}'
+ '.tr-d.today .tr-n{background:' + T.accent + ';color:#fff;font-weight:600;}'
+ '.tr-m{font-size:10px;font-weight:600;color:' + T.ink3 + ';line-height:1;margin-top:-2px;}'
+ '.tr-dots{display:flex;gap:3px;height:7px;}'
+ '.tr-dot{width:7px;height:7px;border-radius:50%;}'
+ '.tr-leg{display:flex;flex-wrap:wrap;gap:6px 14px;margin-top:12px;font-size:13px;color:' + T.ink2 + ';}'
+ '.tr-leg span{display:inline-flex;align-items:center;gap:6px;}'
+ '.tr-mo{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:4px;}'
+ '.tr-mc{height:30px;border-radius:8px;display:grid;place-items:center;font-size:12px;font-weight:600;color:' + T.ink3 + ';background:' + T.fill + ';}'
+ '.tr-mc.duty{background:' + T.accent + ';color:#fff;}'
+ '.tr-mc.now{box-shadow:inset 0 0 0 2px ' + T.ink + ';color:' + T.ink + ';}'
+ '.tr-mc.duty.now{color:#fff;}'
+ '</style>';

const heroH = UI.hero(first
? { label: (UI.soft && UI.soft()) ? null : 'Nächste Abholung', value: first.label,
sub: rel(first.days) + ' · ' + fmt(first.next) + (first.days === 1 ? ' · heute Abend raus' : ''),
subTone: first.days <= 1 ? 'warn' : null, center: true }
: { value: 'Keine Termine', center: true });

let calH = '', rightH = '';
if (bins.length) {
const start = new Date(today); start.setDate(start.getDate() - ((start.getDay() + 6) % 7));
let g = '<div class="tr-cal">' + ['Mo', 'Di', 'Mi', 'Do', 'Fr', 'Sa', 'So'].map((w) => '<div class="tr-wd">' + w + '</div>').join('');
for (let i = 0; i < 28; i++) {
const d = new Date(start); d.setDate(start.getDate() + i);
const hits = byDay[key(d)] || [];
const cls = 'tr-d' + (d < today ? ' past' : '') + (+d === +today ? ' today' : '') + (hits.length && d >= today ? ' hit' : '');
g += '<div class="' + cls + '" title="' + esc(hits.map((b) => b.label).join(', ')) + '">'
+ (d.getDate() === 1 ? '<div class="tr-m">' + MON[d.getMonth()] + '</div>' : '')
+ '<div class="tr-n">' + d.getDate() + '</div>'
+ '<div class="tr-dots">' + hits.map((b) => '<div class="tr-dot" style="background:' + b.color + '"></div>').join('') + '</div></div>';
}
g += '</div><div class="tr-leg">' + BINS.filter((b) => bins.some((x) => x.id === b.id))
.map((b) => '<span><i class="tr-dot" style="display:inline-block;background:' + b.color + '"></i>' + esc(b.label) + '</span>').join('') + '</div>';
calH = title('Nächste 4 Wochen') + plate(g);
}

if (bins.length) {
const rows = bins.map((b) => {
const rhythm = b.weeks === 1 ? 'jede Woche' : b.weeks > 1 ? 'alle ' + b.weeks + ' Wochen' : null;
return {
icon: 'mdi:trash-can', iconTone: b.color,
label: b.label,
sub: fmt(b.next) + (rhythm ? ' · ' + rhythm : ''),
value: rel(b.days),
valueTone: b.days <= 1 ? 'warn' : null,
};
});
rightH += UI.group(rows, 'Tonnen');
}

const moved = [];
bins.forEach((b) => {
if (b.usual == null) return;
b.ds.forEach((d) => { if (diff(d) <= 120 && d.getDay() !== b.usual) moved.push({ b, d }); });
});
moved.sort((x, y) => x.d - y.d);
if (false && moved.length) {
rightH += (rightH ? gap : '') + UI.group(moved.slice(0, 4).map((m) => ({
icon: 'mdi:calendar-alert', iconTone: m.b.color,
label: m.b.label + ' am ' + WD[m.d.getDay()],
sub: fmtS(m.d) + ' statt ' + WD[m.b.usual],
value: rel(diff(m.d)),
})), 'Verschobene Termine');
}

const cm = today.getMonth() + 1;
let nextDuty = null;
for (let i = 1; i <= 12 && nextDuty == null; i++) { const m = ((cm - 1 + i) % 12) + 1; if (DUTY.indexOf(m) > -1) nextDuty = m; }
const mo = '<div class="tr-mo">' + MON.map((n, i) => '<div class="tr-mc' + (DUTY.indexOf(i + 1) > -1 ? ' duty' : '')
+ (i + 1 === cm ? ' now' : '') + '">' + n.charAt(0) + '</div>').join('') + '</div>'
+ '<div style="font-size:13px;color:' + T.ink3 + ';margin-top:10px;">'
+ esc(duty ? 'Diesen Monat bist du dran' + (nextDuty ? ', danach wieder im ' + MONL[nextDuty - 1] : '') + '.'
: 'Nächster Dienst im ' + (nextDuty ? MONL[nextDuty - 1] : '–') + '.') + '</div>';
const dutyTxt = duty ? 'Du bist dran' : 'Nicht dran';
const dutyLbl = UI.soft && UI.soft() && UI.label
? UI.label('Rausstellen').slice(0, -6) + '<div style="font-size:13px;font-weight:600;white-space:nowrap;color:' + (duty ? T.green : T.ink3) + ';">' + esc(dutyTxt) + '</div></div>'
: title('Rausstellen', dutyTxt, duty ? T.green : null);
const dutyH = dutyLbl + plate(mo);

const REM_HEAD = title('Erinnerung').replace('padding:0 4px 8px;', 'padding:0 0 10px;');
