casora_weather_warning.name:
[[[
const ids = (variables.sensors && variables.sensors.length > 0) ? variables.sensors : [entity?.entity_id];
const order = ['Extrem', 'Severe', 'Moderate', 'Minor'];
const active = ids
.map(id => states[id])
.filter(s => s && s.state === 'on')
.sort((a, b) => order.indexOf(a.attributes?.severity) - order.indexOf(b.attributes?.severity));

const isMobile = window.matchMedia('(max-width: 767px), (max-height: 600px)').matches;

if (!active.length) return "NINA";

const text = variables.levels[active[0].attributes?.severity]?.text;
if (!text) return "NINA";

return isMobile ? text : "NINA - " + text;
]]]

card.--casora-icon-color-current:
[[[
const ids = (variables.sensors && variables.sensors.length > 0) ? variables.sensors : [entity?.entity_id];
const sev = s => s === 'Extrem' ? 4 : s === 'Severe' ? 3 : s === 'Moderate' ? 2 : s === 'Minor' ? 1 : 0;
const max = ids
.map(id => states[id])
.filter(s => s?.state === 'on')
.reduce((m, s) => Math.max(m, sev(s.attributes?.severity)), 0);
if (max >= 4) return 'var(--casora-color-purple, #9333ea)';
if (max === 3) return 'var(--casora-color-red, #FF4245)';
if (max === 2) return 'var(--casora-color-orange, #FF9230)';
return 'var(--casora-color-yellow, #FFCC00)';
]]]

